import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.4";
import postgres from "https://deno.land/x/postgresjs@v3.4.5/mod.js";

/**
 * DDL delivery vehicle for app schema changes.
 *
 * The remote migration history does not match `supabase/migrations/`, so
 * `supabase db push` would replay destructive early migrations and must never
 * be run. Schema changes reach the live database the same way the rest of this
 * project's have: an admin-gated edge function that opens `SUPABASE_DB_URL` and
 * applies idempotent SQL.
 *
 * `SETUP_SQL` is generated from the migration list in
 * `tools/embed-schema-setup-sql.cjs` — add new migrations there and regenerate
 * rather than hand-editing the constant. Everything it carries is written to be
 * safely re-runnable, so applying it twice is a no-op.
 *
 * Both actions are admin-only. `setup` runs the DDL; `verify` is read-only and
 * reports whether it landed.
 */

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";
const SUPABASE_DB_URL = Deno.env.get("SUPABASE_DB_URL") || "";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const SETUP_SQL = "-- ---------------------------------------------------------------------------\r\n-- Collection time slots\r\n--\r\n-- Customers pick a two-hour window between 07:00 and 23:00 for the day their\r\n-- goods are collected; dispatch plans the route around those windows and, when\r\n-- it has to move somebody, owes them a WhatsApp or a phone call.\r\n--\r\n-- The whole feature hangs off knowing *when* a collection is, and that was not\r\n-- previously knowable in SQL: `collection_schedules.pickup_date` is free text\r\n-- and holds \"September 14th, 2026\", \"2026-08-04\" and \"04/08/2026\" side by side.\r\n-- Section A gives every schedule a real `date` alongside it so a reminder can\r\n-- be timed 48 hours out.\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. A real date for every published schedule\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- `public.parse_schedule_date(p_text)` already exists (added by\r\n-- 20260810_driver_route_collections.sql) and is depended on by the driver\r\n-- collection-matching functions. It is reused here rather than redefined —\r\n-- redefining it under a different parameter name is what this migration first\r\n-- tried, and Postgres rightly refused with \"cannot change name of input\r\n-- parameter\". Verified against every format the live schedules actually use:\r\n-- \"September 14th, 2026\", \"2026-08-04\", \"May 7th, 2026\" and\r\n-- \"Thursday, 3 September 2026\" all parse correctly.\r\n--\r\n-- Known divergence, currently unexercised: it resolves \"04/08/2026\" through\r\n-- `::date` and so reads it as 8 April, where the apps' `parseCollectionDate`\r\n-- reads day/month and gets 4 August. No published schedule uses that format.\r\n-- Changing the shared function would move the driver matching too, so this is\r\n-- documented rather than \"fixed\" here.\r\n\r\nalter table public.collection_schedules add column if not exists pickup_on date;\r\n\r\ncreate or replace function public.sync_schedule_pickup_on()\r\nreturns trigger language plpgsql set search_path = public as $$\r\nbegin\r\n  new.pickup_on := public.parse_schedule_date(new.pickup_date);\r\n  return new;\r\nend $$;\r\n\r\ndrop trigger if exists collection_schedule_pickup_on on public.collection_schedules;\r\ncreate trigger collection_schedule_pickup_on\r\n  before insert or update of pickup_date on public.collection_schedules\r\n  for each row execute function public.sync_schedule_pickup_on();\r\n\r\nupdate public.collection_schedules\r\n   set pickup_on = public.parse_schedule_date(pickup_date)\r\n where pickup_on is distinct from public.parse_schedule_date(pickup_date);\r\n\r\ncreate index if not exists collection_schedules_pickup_on_idx on public.collection_schedules(pickup_on);\r\n\r\n-- The date a given booking is being collected on: the linked schedule when\r\n-- there is one, otherwise whatever the booking recorded for itself.\r\ncreate or replace function public.shipment_collection_date(p_schedule_id uuid, p_metadata jsonb)\r\nreturns date language sql stable set search_path = public as $$\r\n  select coalesce(\r\n    (select cs.pickup_on from public.collection_schedules cs where cs.id = p_schedule_id),\r\n    public.parse_schedule_date(p_metadata->'collection'->>'date')\r\n  )\r\n$$;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. The slot itself\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.collection_slots (\r\n  id uuid primary key default gen_random_uuid(),\r\n  shipment_id uuid not null unique references public.shipments(id) on delete cascade,\r\n  user_id uuid references auth.users(id) on delete set null,\r\n  collection_date date,\r\n  route text,\r\n\r\n  -- What the customer asked for. `requested_flexible` is \"any time is fine\",\r\n  -- which is a real answer and not the same as never having replied.\r\n  requested_start time,\r\n  requested_end time,\r\n  requested_flexible boolean not null default false,\r\n  requested_at timestamptz,\r\n\r\n  -- What dispatch settled on once the route was sequenced.\r\n  dispatch_start time,\r\n  dispatch_end time,\r\n  dispatch_set_at timestamptz,\r\n  dispatch_set_by uuid references auth.users(id) on delete set null,\r\n  change_reason text,\r\n\r\n  -- Proof that somebody actually spoke to the customer about a change.\r\n  customer_informed_at timestamptz,\r\n  customer_informed_by uuid references auth.users(id) on delete set null,\r\n  customer_informed_via text check (customer_informed_via in ('whatsapp', 'call', 'sms', 'in_person')),\r\n  customer_informed_note text,\r\n\r\n  reminder_sent_at timestamptz,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists collection_slots_date_idx on public.collection_slots(collection_date);\r\ncreate index if not exists collection_slots_user_idx on public.collection_slots(user_id);\r\n\r\ndo $$ begin\r\n  alter table public.collection_slots add constraint collection_slot_requested_window\r\n    check (\r\n      requested_start is null or requested_end is null\r\n      or (requested_start >= time '07:00' and requested_end <= time '23:00' and requested_end > requested_start)\r\n    );\r\nexception when duplicate_object then null; end $$;\r\n\r\ndo $$ begin\r\n  alter table public.collection_slots add constraint collection_slot_dispatch_window\r\n    check (\r\n      dispatch_start is null or dispatch_end is null\r\n      or (dispatch_start >= time '07:00' and dispatch_end <= time '23:00' and dispatch_end > dispatch_start)\r\n    );\r\nexception when duplicate_object then null; end $$;\r\n\r\ncreate or replace function public.touch_collection_slot()\r\nreturns trigger language plpgsql set search_path = public as $$\r\nbegin new.updated_at := now(); return new; end $$;\r\n\r\ndrop trigger if exists collection_slots_touch on public.collection_slots;\r\ncreate trigger collection_slots_touch before update on public.collection_slots\r\n  for each row execute function public.touch_collection_slot();\r\n\r\nalter table public.collection_slots enable row level security;\r\n\r\n-- Customers read their own slot; every write goes through the RPCs below so the\r\n-- 07:00-23:00 rule and the \"who changed this\" trail cannot be sidestepped.\r\ndrop policy if exists \"Customers read own collection slot\" on public.collection_slots;\r\ncreate policy \"Customers read own collection slot\" on public.collection_slots\r\n  for select to authenticated using (user_id = auth.uid());\r\n\r\ndrop policy if exists \"Operations manage collection slots\" on public.collection_slots;\r\ncreate policy \"Operations manage collection slots\" on public.collection_slots\r\n  for all to authenticated\r\n  using (public.is_operations_admin()) with check (public.is_operations_admin());\r\n\r\n-- A driver working the stop needs to know when the customer said they would be\r\n-- in, without being able to see anybody else's day.\r\ndrop policy if exists \"Drivers read slots on their runs\" on public.collection_slots;\r\ncreate policy \"Drivers read slots on their runs\" on public.collection_slots\r\n  for select to authenticated using (\r\n    exists (\r\n      select 1 from public.driver_run_stops st\r\n      join public.driver_runs r on r.id = st.run_id\r\n      where st.shipment_id = collection_slots.shipment_id and r.driver_id = auth.uid()\r\n    )\r\n  );\r\n\r\n-- Make sure a row exists for a booking, filling in the date and route from the\r\n-- booking itself. Returns the row id.\r\ncreate or replace function public.ensure_collection_slot(p_shipment_id uuid)\r\nreturns uuid language plpgsql security definer set search_path = public as $$\r\ndeclare v_ship public.shipments%rowtype; v_date date; v_route text; v_id uuid;\r\nbegin\r\n  select * into v_ship from public.shipments where id = p_shipment_id;\r\n  if not found then raise exception 'Shipment not found'; end if;\r\n\r\n  v_date := public.shipment_collection_date(v_ship.collection_schedule_id, v_ship.metadata);\r\n  v_route := coalesce(\r\n    (select cs.route from public.collection_schedules cs where cs.id = v_ship.collection_schedule_id),\r\n    nullif(v_ship.metadata->'collection'->>'route', 'To be assigned'));\r\n\r\n  insert into public.collection_slots (shipment_id, user_id, collection_date, route)\r\n  values (p_shipment_id, v_ship.user_id, v_date, v_route)\r\n  on conflict (shipment_id) do update\r\n    set collection_date = coalesce(excluded.collection_date, collection_slots.collection_date),\r\n        route = coalesce(excluded.route, collection_slots.route),\r\n        user_id = coalesce(collection_slots.user_id, excluded.user_id)\r\n  returning id into v_id;\r\n  return v_id;\r\nend $$;\r\n\r\nrevoke all on function public.ensure_collection_slot(uuid) from public, anon, authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. The customer's half\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * The customer confirms when they will be in. Passing p_flexible skips the\r\n * window entirely and tells dispatch any time on the day suits.\r\n */\r\ncreate or replace function public.confirm_collection_slot(\r\n  p_shipment_id uuid,\r\n  p_start time default null,\r\n  p_end time default null,\r\n  p_flexible boolean default false\r\n) returns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare v_ship public.shipments%rowtype; v_slot public.collection_slots%rowtype;\r\nbegin\r\n  if auth.uid() is null then raise exception 'Sign in to confirm your collection time'; end if;\r\n\r\n  select * into v_ship from public.shipments where id = p_shipment_id;\r\n  if not found or v_ship.user_id is distinct from auth.uid() then\r\n    raise exception 'That booking is not yours';\r\n  end if;\r\n  if coalesce(v_ship.collection_status, 'Awaiting Collection') = 'Collected' then\r\n    raise exception 'This shipment has already been collected';\r\n  end if;\r\n\r\n  if not p_flexible then\r\n    if p_start is null or p_end is null then raise exception 'Choose a collection window'; end if;\r\n    if p_start < time '07:00' or p_end > time '23:00' or p_end <= p_start then\r\n      raise exception 'Collection windows run between 07:00 and 23:00';\r\n    end if;\r\n  end if;\r\n\r\n  perform public.ensure_collection_slot(p_shipment_id);\r\n\r\n  update public.collection_slots set\r\n    requested_start = case when p_flexible then null else p_start end,\r\n    requested_end = case when p_flexible then null else p_end end,\r\n    requested_flexible = p_flexible,\r\n    requested_at = now()\r\n  where shipment_id = p_shipment_id\r\n  returning * into v_slot;\r\n\r\n  return to_jsonb(v_slot);\r\nend $$;\r\n\r\nrevoke all on function public.confirm_collection_slot(uuid, time, time, boolean) from public, anon;\r\ngrant execute on function public.confirm_collection_slot(uuid, time, time, boolean) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Dispatch's half\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Dispatch records the window it can actually work to. When that differs from\r\n * what the customer asked for, the customer is notified in the app straight\r\n * away — but an in-app notice is not a conversation, so the slot is left\r\n * flagged until somebody records a WhatsApp or a call against it.\r\n */\r\ncreate or replace function public.dispatch_set_collection_slot(\r\n  p_shipment_id uuid,\r\n  p_start time,\r\n  p_end time,\r\n  p_reason text default null\r\n) returns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare v_slot public.collection_slots%rowtype; v_ship public.shipments%rowtype; v_moved boolean;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Only dispatch can set collection windows'; end if;\r\n  if p_start is null or p_end is null then raise exception 'A dispatch window needs a start and an end'; end if;\r\n  if p_start < time '07:00' or p_end > time '23:00' or p_end <= p_start then\r\n    raise exception 'Collection windows run between 07:00 and 23:00';\r\n  end if;\r\n\r\n  perform public.ensure_collection_slot(p_shipment_id);\r\n  select * into v_slot from public.collection_slots where shipment_id = p_shipment_id;\r\n\r\n  -- \"Moved\" means moved away from something the customer actually asked for.\r\n  -- A customer who said any time is fine, or who never replied, has not been\r\n  -- moved and generates no obligation.\r\n  v_moved := v_slot.requested_at is not null\r\n         and not v_slot.requested_flexible\r\n         and (v_slot.requested_start is distinct from p_start or v_slot.requested_end is distinct from p_end);\r\n\r\n  update public.collection_slots set\r\n    dispatch_start = p_start,\r\n    dispatch_end = p_end,\r\n    dispatch_set_at = now(),\r\n    dispatch_set_by = auth.uid(),\r\n    change_reason = nullif(btrim(coalesce(p_reason, '')), '')\r\n  where shipment_id = p_shipment_id\r\n  returning * into v_slot;\r\n\r\n  if v_moved then\r\n    select * into v_ship from public.shipments where id = p_shipment_id;\r\n    if v_ship.user_id is not null then\r\n      insert into public.notifications (user_id, title, message, type, related_id)\r\n      values (\r\n        v_ship.user_id,\r\n        'Your collection time has changed',\r\n        coalesce(v_ship.customer_reference, v_ship.tracking_number)\r\n          || ': we now plan to collect between ' || substring(p_start::text from 1 for 5)\r\n          || ' and ' || substring(p_end::text from 1 for 5)\r\n          || coalesce(' on ' || to_char(v_slot.collection_date, 'FMDay FMDD FMMonth'), '')\r\n          || '.' || coalesce(' ' || v_slot.change_reason, ''),\r\n        'shipment',\r\n        p_shipment_id);\r\n    end if;\r\n  end if;\r\n\r\n  return to_jsonb(v_slot) || jsonb_build_object('moved', v_moved);\r\nend $$;\r\n\r\nrevoke all on function public.dispatch_set_collection_slot(uuid, time, time, text) from public, anon;\r\ngrant execute on function public.dispatch_set_collection_slot(uuid, time, time, text) to authenticated;\r\n\r\n/** Records that somebody actually reached the customer about a change. */\r\ncreate or replace function public.mark_collection_customer_informed(\r\n  p_shipment_id uuid,\r\n  p_via text,\r\n  p_note text default null\r\n) returns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare v_slot public.collection_slots%rowtype;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Only dispatch can close a customer contact'; end if;\r\n  if p_via not in ('whatsapp', 'call', 'sms', 'in_person') then raise exception 'Unknown contact method'; end if;\r\n\r\n  update public.collection_slots set\r\n    customer_informed_at = now(),\r\n    customer_informed_by = auth.uid(),\r\n    customer_informed_via = p_via,\r\n    customer_informed_note = nullif(btrim(coalesce(p_note, '')), '')\r\n  where shipment_id = p_shipment_id\r\n  returning * into v_slot;\r\n\r\n  if not found then raise exception 'No collection slot for that booking'; end if;\r\n  return to_jsonb(v_slot);\r\nend $$;\r\n\r\nrevoke all on function public.mark_collection_customer_informed(uuid, text, text) from public, anon;\r\ngrant execute on function public.mark_collection_customer_informed(uuid, text, text) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- E. The 48-hour reminder\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Two days before a collection, offer everybody booked onto it a window.\r\n *\r\n * The offer is optional and the wording says so: a customer who ignores it is\r\n * not chased again and is not treated as a problem, because dispatch plans the\r\n * round perfectly well without an answer. `reminder_sent_at` makes this\r\n * once-only per booking, so a retry or a second run on the same day cannot\r\n * message anyone twice.\r\n */\r\ncreate or replace function public.queue_collection_slot_reminders()\r\nreturns integer language plpgsql security definer set search_path = public as $$\r\ndeclare v_target date := current_date + 2; v_count integer := 0; v_row record;\r\nbegin\r\n  for v_row in\r\n    select s.id, s.user_id, s.customer_reference, s.tracking_number,\r\n           public.shipment_collection_date(s.collection_schedule_id, s.metadata) as collect_on\r\n      from public.shipments s\r\n     where s.deleted_at is null\r\n       and s.user_id is not null\r\n       and coalesce(s.collection_status, 'Awaiting Collection') <> 'Collected'\r\n       and public.shipment_collection_date(s.collection_schedule_id, s.metadata) = v_target\r\n       and coalesce((select (p.notification_preferences->>'shipment')::boolean\r\n                       from public.profiles p where p.id = s.user_id), true)\r\n       and not exists (\r\n         select 1 from public.collection_slots cs\r\n          where cs.shipment_id = s.id and cs.reminder_sent_at is not null)\r\n  loop\r\n    perform public.ensure_collection_slot(v_row.id);\r\n\r\n    insert into public.notifications (user_id, title, message, type, related_id)\r\n    values (\r\n      v_row.user_id,\r\n      'Your collection is in two days',\r\n      coalesce(v_row.customer_reference, v_row.tracking_number)\r\n        || ' is being collected on ' || to_char(v_row.collect_on, 'FMDay FMDD FMMonth')\r\n        || '. If a particular time suits you better, pick a two-hour window between 7am and 11pm in the app —'\r\n        || ' otherwise the driver will call ahead on the day.',\r\n      'shipment',\r\n      v_row.id);\r\n\r\n    update public.collection_slots set reminder_sent_at = now() where shipment_id = v_row.id;\r\n    v_count := v_count + 1;\r\n  end loop;\r\n\r\n  return v_count;\r\nend $$;\r\n\r\nrevoke all on function public.queue_collection_slot_reminders() from public, anon, authenticated;\r\ngrant execute on function public.queue_collection_slot_reminders() to service_role;\r\n\r\n-- 08:00 UTC daily: a Saturday collection asks on Thursday morning, which leaves\r\n-- two working days for dispatch to react to the answers.\r\ndo $$ begin create extension if not exists pg_cron; exception when others then null; end $$;\r\ndo $$\r\nbegin\r\n  if exists (select 1 from pg_extension where extname = 'pg_cron') then\r\n    perform cron.unschedule(jobid) from cron.job where jobname = 'collection-slot-reminders';\r\n    perform cron.schedule(\r\n      'collection-slot-reminders',\r\n      '0 8 * * *',\r\n      $job$select public.queue_collection_slot_reminders();$job$);\r\n  end if;\r\nexception when others then null;\r\nend $$;\r\n\n\n-- ---------------------------------------------------------------------------\r\n-- Saved pickup addresses, and buying drums from us\r\n--\r\n-- Two things customers could not do from the app:\r\n--\r\n--   1. Save the address we collect FROM. Saved addresses existed only for\r\n--      Zimbabwe delivery; the collection address lived as three loose columns\r\n--      on `profiles`, so a customer with two pickup addresses (home and their\r\n--      mother's) had to retype one of them on every booking.\r\n--   2. Buy a drum from us. The website has offered this for a while; the app\r\n--      never did, so app customers had to ask on WhatsApp.\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. Pickup addresses share the delivery-address table\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- One table, two kinds. The columns already fit both: for a pickup address the\r\n-- \"recipient\" is whoever hands the goods over, which is normally the customer.\r\n-- A separate table would have meant duplicating the RLS, the default handling\r\n-- and every screen that reads them.\r\nalter table public.customer_addresses\r\n  add column if not exists address_type text not null default 'delivery';\r\n\r\ndo $$ begin\r\n  alter table public.customer_addresses add constraint customer_address_type_check\r\n    check (address_type in ('delivery', 'pickup'));\r\nexception when duplicate_object then null; end $$;\r\n\r\n-- Everything that existed before this migration is a Zimbabwe delivery address.\r\nupdate public.customer_addresses set address_type = 'delivery' where address_type is null;\r\n\r\ncreate index if not exists customer_addresses_user_type_idx\r\n  on public.customer_addresses(user_id, address_type);\r\n\r\n/**\r\n * Give every customer who onboarded with a pickup address a saved pickup\r\n * address to match, so the feature is useful on first open rather than empty.\r\n *\r\n * Deliberately additive: the `profiles` columns are left exactly as they are,\r\n * because the website's booking form still reads them. This only ever inserts,\r\n * only for customers with no pickup address saved yet, so re-running it is a\r\n * no-op rather than a pile of duplicates.\r\n */\r\ninsert into public.customer_addresses (\r\n  user_id, address_type, recipient_name, recipient_phone,\r\n  address_line1, city, postal_code, country, is_default)\r\nselect\r\n  p.id,\r\n  'pickup',\r\n  coalesce(nullif(btrim(p.full_name), ''), 'Me'),\r\n  coalesce(p.phone_number, ''),\r\n  btrim(p.pickup_address),\r\n  coalesce(nullif(btrim(p.pickup_city), ''), ''),\r\n  p.postal_code,\r\n  case when lower(coalesce(p.country, '')) like '%ireland%' then 'Ireland' else 'United Kingdom' end,\r\n  true\r\nfrom public.profiles p\r\nwhere coalesce(btrim(p.pickup_address), '') <> ''\r\n  and not exists (\r\n    select 1 from public.customer_addresses a\r\n     where a.user_id = p.id and a.address_type = 'pickup');\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. Buying drums from us\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- The purchase prices are the same number in either currency, matching how the\r\n-- collection and door-delivery fees already work (GBP 25 / EUR 25).\r\nupdate public.app_configuration\r\n   set value = value\r\n     || jsonb_build_object('metalDrumPurchase', coalesce((value->>'metalDrumPurchase')::numeric, 40))\r\n     || jsonb_build_object('plasticDrumPurchase', coalesce((value->>'plasticDrumPurchase')::numeric, 50))\r\n where key = 'booking_fees';\r\n\r\n-- Step aside so the current booking function can be wrapped rather than\r\n-- rewritten. Guarded on the target name, exactly as the earlier booking\r\n-- migrations did it, so re-running this file renames nothing a second time.\r\ndo $$ begin\r\n  if to_regprocedure('public.create_customer_booking_v2(jsonb)') is null then\r\n    execute 'alter function public.create_customer_booking(jsonb) rename to create_customer_booking_v2';\r\n  end if;\r\nend $$;\r\n\r\n/**\r\n * Price purchased drums server-side, like everything else on a booking.\r\n *\r\n * This wraps the wrapper: `create_customer_booking` already delegates the bulk\r\n * of the work to `create_customer_booking_legacy` and then corrects the invoice\r\n * for door delivery and quote items. Purchased drums are appended the same way,\r\n * at the fee held in `app_configuration` rather than anything the client sent —\r\n * a client that asks for cheap drums gets charged the configured price.\r\n */\r\ncreate or replace function public.create_customer_booking(p jsonb) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_result jsonb; v_shipment_id uuid; v_ship public.shipments%rowtype;\r\n  v_invoice jsonb; v_meta jsonb; v_lines jsonb; v_total numeric;\r\n  v_drum_type text; v_drum_qty integer; v_drum_price numeric; v_drum_label text;\r\nbegin\r\n  -- Everything the previous version did stays exactly as it was.\r\n  v_result := public.create_customer_booking_v2(p);\r\n\r\n  v_drum_type := nullif(p->'purchaseDrums'->>'type', '');\r\n  v_drum_qty := greatest(0, coalesce((p->'purchaseDrums'->>'quantity')::integer, 0));\r\n  if v_drum_type is null or v_drum_qty = 0 then return v_result; end if;\r\n  if v_drum_type not in ('metal', 'plastic') then raise exception 'Unknown drum type'; end if;\r\n\r\n  v_drum_price := public.config_number('booking_fees',\r\n    case when v_drum_type = 'metal' then 'metalDrumPurchase' else 'plasticDrumPurchase' end, 0);\r\n  if v_drum_price <= 0 then return v_result; end if;\r\n\r\n  v_drum_label := case when v_drum_type = 'metal' then 'Metal drum purchased from us' else 'Plastic barrel purchased from us' end;\r\n\r\n  v_shipment_id := (v_result->>'id')::uuid;\r\n  select * into v_ship from public.shipments where id = v_shipment_id for update;\r\n  v_invoice := coalesce(v_ship.metadata->'invoice', '{}'::jsonb);\r\n  v_lines := coalesce(v_invoice->'items', '[]'::jsonb)\r\n    || jsonb_build_array(jsonb_build_object(\r\n         'description', v_drum_label, 'quantity', v_drum_qty, 'unitPrice', v_drum_price));\r\n  v_total := coalesce((v_result->>'estimatedTotal')::numeric, 0) + (v_drum_qty * v_drum_price);\r\n\r\n  v_invoice := jsonb_set(v_invoice, '{items}', v_lines, true);\r\n  v_meta := jsonb_set(coalesce(v_ship.metadata, '{}'::jsonb), '{invoice}', v_invoice, true);\r\n  v_meta := jsonb_set(v_meta, '{pricing,estimatedTotal}', to_jsonb(v_total), true);\r\n  -- Same shape the website writes, so warehouse and finance read one format.\r\n  v_meta := jsonb_set(v_meta, '{purchasedDrums}', jsonb_build_object(\r\n    'type', v_drum_type, 'quantity', v_drum_qty,\r\n    'priceEach', v_drum_price, 'totalPrice', v_drum_qty * v_drum_price), true);\r\n\r\n  update public.shipments set metadata = v_meta where id = v_shipment_id;\r\n  return v_result || jsonb_build_object('estimatedTotal', v_total, 'invoice', v_invoice);\r\nend $$;\r\n\r\ngrant execute on function public.create_customer_booking(jsonb) to authenticated;\r\n\n\n-- ---------------------------------------------------------------------------\r\n-- Collection runs: giving a collection period an identity\r\n--\r\n-- Dispatch could not group work by \"the Northampton run on the 14th\" because\r\n-- nothing in the database represented that. `collection_schedules` holds one\r\n-- row per ROUTE and its `pickup_date` is edited in place\r\n-- (`update ... set pickup_date = new_date where route = route_name`), so the\r\n-- schedule id identifies a route, not an occurrence of it: move the date and\r\n-- every shipment ever linked to that route appears to belong to the new date.\r\n--\r\n-- The shape of the problem in the live data before this migration:\r\n--   * 278 shipments read as awaiting collection, of which only 11 carried a\r\n--     schedule link at all.\r\n--   * 83 distinct route/date pairs, dominated by \"(no route) | (no date)\" (71)\r\n--     and \"To be assigned | To be confirmed\" (35).\r\n--   * Route names recorded inconsistently — BRIGHTON vs BRIGHTON ROUTE, LEEDS\r\n--     vs LEEDS ROUTE, SOUTHEND vs SOUTHEND ROUTE.\r\n--\r\n-- A `collection_run` is one route on one date. Shipments attach to it\r\n-- automatically as they are booked, whichever booking path they came in\r\n-- through, and dispatch opens a run to work it.\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. The run\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.collection_runs (\r\n  id uuid primary key default gen_random_uuid(),\r\n  schedule_id uuid references public.collection_schedules(id) on delete set null,\r\n  route text not null,\r\n  country text,\r\n  -- Null while the office has not published the next date for this route. The\r\n  -- run still exists and still gathers bookings; it simply has no date yet.\r\n  collection_date date,\r\n  status text not null default 'planned'\r\n    check (status in ('planned', 'active', 'completed', 'cancelled')),\r\n  driver_run_id uuid references public.driver_runs(id) on delete set null,\r\n  notes text,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\n-- One run per route per date. Nulls compare as distinct in a plain unique\r\n-- index, so the undated run is pinned to a sentinel to keep it single.\r\ncreate unique index if not exists collection_runs_route_date_key\r\n  on public.collection_runs (route, coalesce(collection_date, date '0001-01-01'));\r\ncreate index if not exists collection_runs_date_idx on public.collection_runs (collection_date);\r\ncreate index if not exists collection_runs_status_idx on public.collection_runs (status);\r\n\r\nalter table public.shipments\r\n  add column if not exists collection_run_id uuid references public.collection_runs(id) on delete set null;\r\ncreate index if not exists shipments_collection_run_idx\r\n  on public.shipments (collection_run_id) where deleted_at is null;\r\n\r\ncreate or replace function public.touch_collection_run()\r\nreturns trigger language plpgsql set search_path = public as $$\r\nbegin new.updated_at := now(); return new; end $$;\r\n\r\ndrop trigger if exists collection_runs_touch on public.collection_runs;\r\ncreate trigger collection_runs_touch before update on public.collection_runs\r\n  for each row execute function public.touch_collection_run();\r\n\r\nalter table public.collection_runs enable row level security;\r\n\r\ndrop policy if exists \"Operations manage collection runs\" on public.collection_runs;\r\ncreate policy \"Operations manage collection runs\" on public.collection_runs\r\n  for all to authenticated\r\n  using (public.is_operations_admin()) with check (public.is_operations_admin());\r\n\r\n-- A driver working the run needs to see it.\r\ndrop policy if exists \"Drivers read their collection runs\" on public.collection_runs;\r\ncreate policy \"Drivers read their collection runs\" on public.collection_runs\r\n  for select to authenticated using (\r\n    exists (select 1 from public.driver_runs r\r\n             where r.id = collection_runs.driver_run_id and r.driver_id = auth.uid()));\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. Working out which route a booking belongs to\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * The canonical route name for whatever was recorded on a booking.\r\n *\r\n * Bookings carry \"BRIGHTON\" where the schedule says \"BRIGHTON ROUTE\" and vice\r\n * versa, so an exact match loses roughly a fifth of them. Compared on letters\r\n * and digits only, with the word ROUTE stripped from both sides.\r\n */\r\ncreate or replace function public.canonical_route_name(p_route text)\r\nreturns text language sql stable set search_path = public as $$\r\n  select cs.route from public.collection_schedules cs\r\n   where regexp_replace(upper(regexp_replace(coalesce(cs.route, ''), '[^A-Za-z0-9]', '', 'g')), 'ROUTE$', '')\r\n       = regexp_replace(upper(regexp_replace(coalesce(p_route, ''), '[^A-Za-z0-9]', '', 'g')), 'ROUTE$', '')\r\n     and coalesce(p_route, '') <> ''\r\n   limit 1\r\n$$;\r\n\r\n/**\r\n * The schedule covering a collection address, mirroring the apps'\r\n * `scheduleMatchesPostcode`.\r\n *\r\n * UK matches the postcode's outward code or the town against the route's areas;\r\n * Ireland has no usable postcode so it matches the town alone. Deliberately\r\n * returns nothing rather than a guess when neither matches — an unassigned\r\n * booking that dispatch can see is far better than a confident wrong route.\r\n */\r\ncreate or replace function public.match_collection_schedule(\r\n  p_postcode text, p_city text, p_country text\r\n) returns public.collection_schedules\r\nlanguage plpgsql stable set search_path = public as $$\r\ndeclare\r\n  v_ireland boolean := lower(coalesce(p_country, '')) like '%ireland%';\r\n  v_code text := upper(regexp_replace(coalesce(p_postcode, ''), '[^A-Za-z0-9]', '', 'g'));\r\n  v_town text := upper(regexp_replace(coalesce(p_city, ''), '[^A-Za-z0-9]', '', 'g'));\r\n  v_outward text;\r\n  v_row public.collection_schedules%rowtype;\r\nbegin\r\n  -- \"LU11AA\" -> \"LU1\"; anything four characters or shorter is already outward.\r\n  v_outward := case when length(v_code) > 4 then left(v_code, length(v_code) - 3) else v_code end;\r\n\r\n  if v_ireland then\r\n    if length(v_town) < 3 then return null; end if;\r\n    select * into v_row from public.collection_schedules cs\r\n     where lower(coalesce(cs.country, '')) like '%ireland%'\r\n       and upper(regexp_replace(cs.areas::text, '[^A-Za-z0-9]', '', 'g')) like '%' || v_town || '%'\r\n     order by cs.pickup_on nulls last limit 1;\r\n    return v_row;\r\n  end if;\r\n\r\n  if length(v_outward) >= 2 then\r\n    select * into v_row from public.collection_schedules cs\r\n     where lower(coalesce(cs.country, 'UK')) not like '%ireland%'\r\n       and upper(regexp_replace(cs.areas::text, '[^A-Za-z0-9]', '', 'g')) like '%' || v_outward || '%'\r\n     order by cs.pickup_on nulls last limit 1;\r\n    if found then return v_row; end if;\r\n  end if;\r\n\r\n  if length(v_town) >= 3 then\r\n    select * into v_row from public.collection_schedules cs\r\n     where lower(coalesce(cs.country, 'UK')) not like '%ireland%'\r\n       and upper(regexp_replace(cs.areas::text, '[^A-Za-z0-9]', '', 'g')) like '%' || v_town || '%'\r\n     order by cs.pickup_on nulls last limit 1;\r\n    return v_row;\r\n  end if;\r\n\r\n  return null;\r\nend $$;\r\n\r\n/** Find or create the run for one route on one date. */\r\ncreate or replace function public.ensure_collection_run(\r\n  p_route text, p_date date, p_schedule_id uuid default null, p_country text default null\r\n) returns uuid language plpgsql security definer set search_path = public as $$\r\ndeclare v_id uuid;\r\nbegin\r\n  if coalesce(btrim(p_route), '') = '' then return null; end if;\r\n\r\n  select id into v_id from public.collection_runs\r\n   where route = p_route and coalesce(collection_date, date '0001-01-01') = coalesce(p_date, date '0001-01-01');\r\n  if found then\r\n    update public.collection_runs\r\n       set schedule_id = coalesce(schedule_id, p_schedule_id),\r\n           country = coalesce(country, p_country)\r\n     where id = v_id;\r\n    return v_id;\r\n  end if;\r\n\r\n  insert into public.collection_runs (schedule_id, route, country, collection_date)\r\n  values (p_schedule_id, p_route, p_country, p_date)\r\n  on conflict do nothing\r\n  returning id into v_id;\r\n\r\n  if v_id is null then\r\n    select id into v_id from public.collection_runs\r\n     where route = p_route and coalesce(collection_date, date '0001-01-01') = coalesce(p_date, date '0001-01-01');\r\n  end if;\r\n  return v_id;\r\nend $$;\r\n\r\nrevoke all on function public.ensure_collection_run(text, date, uuid, text) from public, anon, authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. Attaching a booking to its run\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Put one shipment in the right run.\r\n *\r\n * Order of preference for the route: the schedule already linked to the\r\n * booking, then the route name the booking recorded (canonicalised), then the\r\n * route the collection postcode resolves to. The date follows the route's\r\n * published date, falling back to whatever the booking recorded.\r\n *\r\n * Returns the run id, or null when nothing could be resolved — which is a\r\n * legitimate outcome and shows in dispatch as unassigned.\r\n */\r\ncreate or replace function public.attach_shipment_to_run(p_shipment_id uuid)\r\nreturns uuid language plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_ship public.shipments%rowtype;\r\n  v_sched public.collection_schedules%rowtype;\r\n  v_sender jsonb; v_route text; v_date date; v_run uuid;\r\nbegin\r\n  select * into v_ship from public.shipments where id = p_shipment_id;\r\n  if not found then return null; end if;\r\n\r\n  if v_ship.collection_schedule_id is not null then\r\n    select * into v_sched from public.collection_schedules where id = v_ship.collection_schedule_id;\r\n  end if;\r\n\r\n  if v_sched.id is null then\r\n    v_route := public.canonical_route_name(nullif(v_ship.metadata->'collection'->>'route', 'To be assigned'));\r\n    if v_route is not null then\r\n      select * into v_sched from public.collection_schedules where route = v_route limit 1;\r\n    end if;\r\n  end if;\r\n\r\n  if v_sched.id is null then\r\n    v_sender := coalesce(v_ship.metadata->'sender', v_ship.metadata->'senderDetails', '{}'::jsonb);\r\n    select * into v_sched from public.match_collection_schedule(\r\n      coalesce(v_sender->>'postalCode', v_sender->>'postcode'),\r\n      v_sender->>'city',\r\n      coalesce(v_sender->>'country', v_ship.metadata->'collection'->>'country'));\r\n  end if;\r\n\r\n  if v_sched.id is null then return null; end if;\r\n\r\n  v_date := coalesce(v_sched.pickup_on, public.parse_schedule_date(v_ship.metadata->'collection'->>'date'));\r\n  v_run := public.ensure_collection_run(v_sched.route, v_date, v_sched.id, v_sched.country);\r\n\r\n  update public.shipments\r\n     set collection_run_id = v_run,\r\n         collection_schedule_id = coalesce(collection_schedule_id, v_sched.id)\r\n   where id = p_shipment_id;\r\n\r\n  return v_run;\r\nend $$;\r\n\r\nrevoke all on function public.attach_shipment_to_run(uuid) from public, anon;\r\ngrant execute on function public.attach_shipment_to_run(uuid) to authenticated;\r\n\r\n/**\r\n * Every new booking joins a run, whichever door it came in through — the app,\r\n * the website, or a manual booking typed by the office. A trigger rather than a\r\n * change to `create_customer_booking`, because there is more than one creator\r\n * and they must not drift apart again.\r\n *\r\n * Never fatal: a booking that cannot be filed is still a booking.\r\n */\r\ncreate or replace function public.attach_new_shipment_to_run()\r\nreturns trigger language plpgsql security definer set search_path = public as $$\r\nbegin\r\n  begin\r\n    perform public.attach_shipment_to_run(new.id);\r\n  exception when others then\r\n    null;\r\n  end;\r\n  return null;\r\nend $$;\r\n\r\ndrop trigger if exists shipment_joins_collection_run on public.shipments;\r\ncreate trigger shipment_joins_collection_run\r\n  after insert on public.shipments\r\n  for each row execute function public.attach_new_shipment_to_run();\r\n\r\n/**\r\n * When the office moves a route's date, the run moves with it.\r\n *\r\n * Without this, editing NORTHAMPTON from the 14th to the 16th would leave the\r\n * existing bookings in a 14th run and start filing new ones into a 16th run —\r\n * splitting one collection into two groups, which is precisely the confusion\r\n * this table exists to remove. Only open runs follow; a completed run keeps the\r\n * date it actually happened on.\r\n */\r\ncreate or replace function public.move_collection_run_with_schedule()\r\nreturns trigger language plpgsql security definer set search_path = public as $$\r\nbegin\r\n  if new.pickup_on is distinct from old.pickup_on then\r\n    -- Skip when a run already sits on the new date, or the unique index trips.\r\n    update public.collection_runs r\r\n       set collection_date = new.pickup_on\r\n     where r.schedule_id = new.id\r\n       and r.status in ('planned', 'active')\r\n       and r.collection_date is distinct from new.pickup_on\r\n       and not exists (\r\n         select 1 from public.collection_runs other\r\n          where other.route = r.route and other.id <> r.id\r\n            and coalesce(other.collection_date, date '0001-01-01') = coalesce(new.pickup_on, date '0001-01-01'));\r\n  end if;\r\n  return new;\r\nend $$;\r\n\r\ndrop trigger if exists collection_run_follows_schedule on public.collection_schedules;\r\ncreate trigger collection_run_follows_schedule\r\n  after update of pickup_on on public.collection_schedules\r\n  for each row execute function public.move_collection_run_with_schedule();\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Backfill\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * File the bookings that are genuinely still waiting to be collected.\r\n *\r\n * Scoped hard on purpose. `collection_status` is stale across this data — 124\r\n * of the 278 shipments it calls uncollected are already In Transit, Arrived or\r\n * Delivered — so `status` is the signal that means anything, and only the\r\n * pre-collection ones are swept in. Sixty days keeps a year of abandoned\r\n * bookings out of next week's run.\r\n */\r\ndo $$\r\ndeclare v_row record; v_count integer := 0;\r\nbegin\r\n  for v_row in\r\n    select s.id from public.shipments s\r\n     where s.deleted_at is null\r\n       and s.collection_run_id is null\r\n       and lower(coalesce(s.status, '')) in ('booking confirmed', 'confirmed', 'pending')\r\n       and s.created_at >= now() - interval '60 days'\r\n  loop\r\n    begin\r\n      perform public.attach_shipment_to_run(v_row.id);\r\n      v_count := v_count + 1;\r\n    exception when others then null;\r\n    end;\r\n  end loop;\r\n  raise notice 'collection runs: considered % pending shipments', v_count;\r\nend $$;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- E. The dispatch board\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * One row per run, with the numbers dispatch actually decides on: how much work\r\n * is in it, how many customers have chosen a time, and whether a driver is on\r\n * it yet. Unassigned bookings are returned as a synthetic run with a null id so\r\n * they sit in the same list rather than being forgotten in another screen.\r\n */\r\ncreate or replace function public.collection_run_board(p_include_done boolean default false)\r\nreturns table (\r\n  run_id uuid, route text, country text, collection_date date, status text,\r\n  driver_run_id uuid, driver_name text,\r\n  shipment_count integer, slots_chosen integer, needs_contact integer\r\n) language sql stable security definer set search_path = public as $$\r\n  select\r\n    r.id, r.route, r.country, r.collection_date, r.status,\r\n    r.driver_run_id,\r\n    -- Not every staff profile has a name filled in, and a nameless driver\r\n    -- must not read as no driver at all.\r\n    (select coalesce(nullif(btrim(p.full_name), ''), p.email) from public.profiles p\r\n      join public.driver_runs dr on dr.driver_id = p.id where dr.id = r.driver_run_id),\r\n    (select count(*)::int from public.shipments s\r\n      where s.collection_run_id = r.id and s.deleted_at is null),\r\n    (select count(*)::int from public.shipments s\r\n      join public.collection_slots cs on cs.shipment_id = s.id\r\n      where s.collection_run_id = r.id and s.deleted_at is null and cs.requested_at is not null),\r\n    (select count(*)::int from public.shipments s\r\n      join public.collection_slots cs on cs.shipment_id = s.id\r\n      where s.collection_run_id = r.id and s.deleted_at is null\r\n        and cs.dispatch_set_at is not null\r\n        and not cs.requested_flexible and cs.requested_at is not null\r\n        and (cs.requested_start is distinct from cs.dispatch_start\r\n          or cs.requested_end is distinct from cs.dispatch_end)\r\n        and (cs.customer_informed_at is null or cs.customer_informed_at < cs.dispatch_set_at))\r\n  from public.collection_runs r\r\n  where public.is_operations_admin()\r\n    and (p_include_done or r.status in ('planned', 'active'))\r\n\r\n  union all\r\n\r\n  -- Recent bookings whose postcode matched no route. These need a human, so\r\n  -- they sit in the same list rather than in a screen nobody opens.\r\n  select\r\n    null::uuid, 'Unassigned', null, null, 'planned', null, null,\r\n    (select count(*)::int from public.shipments s\r\n      where s.deleted_at is null and s.collection_run_id is null\r\n        and lower(coalesce(s.status, '')) in ('booking confirmed', 'confirmed', 'pending')\r\n        and s.created_at >= now() - interval '60 days'),\r\n    0, 0\r\n  where public.is_operations_admin()\r\n\r\n  union all\r\n\r\n  -- Older pending bookings, counted but kept out of the working set. Most are\r\n  -- abandoned; burying this week's real stragglers among a year of them was\r\n  -- what made the flat list unusable in the first place.\r\n  select\r\n    null::uuid, 'Older than 60 days', null, null, 'planned', null, null,\r\n    (select count(*)::int from public.shipments s\r\n      where s.deleted_at is null and s.collection_run_id is null\r\n        and lower(coalesce(s.status, '')) in ('booking confirmed', 'confirmed', 'pending')\r\n        and s.created_at < now() - interval '60 days'),\r\n    0, 0\r\n  where public.is_operations_admin()\r\n\r\n  order by 4 nulls last, 2\r\n$$;\r\n\r\nrevoke all on function public.collection_run_board(boolean) from public, anon;\r\ngrant execute on function public.collection_run_board(boolean) to authenticated;\r\n\n\n-- ---------------------------------------------------------------------------\r\n-- Assigning a driver to a whole collection group\r\n--\r\n-- The group already is the route: everything collecting on the Northampton run\r\n-- on the 14th. Making dispatch re-pick those same shipments one by one in the\r\n-- route builder just to name a driver was the remaining piece of busywork, so\r\n-- this does the whole thing in one call — create or reuse the driver's run for\r\n-- that day, put every collection in the group on it, order the stops by the\r\n-- windows customers actually asked for, and tie the group to the run.\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Put a driver on a collection group.\r\n *\r\n * Passing a null driver unassigns the group and cancels the run it created,\r\n * which is what dispatch wants when a driver calls in sick and the work has to\r\n * go back in the pool.\r\n *\r\n * Stops are ordered by the customer's requested window, earliest first, with\r\n * everyone who did not choose one after them. That is the whole point of asking\r\n * for windows: a route sequenced against them is a route that keeps its\r\n * promises. Where a customer chose a window it is also recorded as the dispatch\r\n * window, so the run reads as agreed rather than as an unanswered question —\r\n * and because it matches what they asked for, nobody is flagged as moved and\r\n * nobody is owed a phone call.\r\n */\r\ncreate or replace function public.assign_collection_run_driver(\r\n  p_run_id uuid,\r\n  p_driver_id uuid,\r\n  p_vehicle text default null\r\n) returns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_run public.collection_runs%rowtype;\r\n  v_driver_run public.driver_runs%rowtype;\r\n  v_driver_run_id uuid;\r\n  v_order integer;\r\n  v_added integer := 0;\r\n  v_row record;\r\n  v_sender jsonb;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Only dispatch can assign a driver'; end if;\r\n\r\n  select * into v_run from public.collection_runs where id = p_run_id for update;\r\n  if not found then raise exception 'Collection group not found'; end if;\r\n\r\n  -- Unassign.\r\n  if p_driver_id is null then\r\n    if v_run.driver_run_id is not null then\r\n      update public.driver_runs set status = 'cancelled', updated_at = now()\r\n       where id = v_run.driver_run_id and status <> 'completed';\r\n      update public.shipments set assigned_driver_id = null\r\n       where collection_run_id = p_run_id and deleted_at is null;\r\n    end if;\r\n    update public.collection_runs\r\n       set driver_run_id = null, status = 'planned' where id = p_run_id;\r\n    return jsonb_build_object('assigned', false, 'stops', 0);\r\n  end if;\r\n\r\n  -- A driver run is filed by date, so an undated group has nothing to file\r\n  -- against. Publishing the route's date is the fix, and saying so is more use\r\n  -- than a constraint violation.\r\n  if v_run.collection_date is null then\r\n    raise exception 'Publish a collection date for % before assigning a driver', v_run.route;\r\n  end if;\r\n\r\n  -- One run per driver per day is a database rule, so reuse theirs if it exists.\r\n  select * into v_driver_run from public.driver_runs\r\n   where driver_id = p_driver_id and run_date = v_run.collection_date;\r\n\r\n  if found then\r\n    v_driver_run_id := v_driver_run.id;\r\n    if v_driver_run.status = 'completed' then\r\n      raise exception 'That driver has already completed their run for this day';\r\n    end if;\r\n    update public.driver_runs\r\n       set route_name = coalesce(route_name, v_run.route),\r\n           vehicle_label = coalesce(p_vehicle, vehicle_label),\r\n           status = case when status = 'cancelled' then 'planned' else status end,\r\n           updated_at = now()\r\n     where id = v_driver_run_id;\r\n  else\r\n    insert into public.driver_runs (driver_id, run_date, status, run_type, route_name, vehicle_label, created_by)\r\n    values (p_driver_id, v_run.collection_date, 'planned', 'pickup', v_run.route, p_vehicle, auth.uid())\r\n    returning id into v_driver_run_id;\r\n  end if;\r\n\r\n  -- Moving the group to a different driver takes its existing stops along, so\r\n  -- nothing has to be rebuilt and no stop is orphaned on the old run.\r\n  if v_run.driver_run_id is not null and v_run.driver_run_id <> v_driver_run_id then\r\n    update public.driver_run_stops st\r\n       set run_id = v_driver_run_id,\r\n           stop_order = st.stop_order\r\n             + (select coalesce(max(stop_order), 0) from public.driver_run_stops where run_id = v_driver_run_id)\r\n     where st.run_id = v_run.driver_run_id\r\n       and st.shipment_id in (select id from public.shipments where collection_run_id = p_run_id)\r\n       and st.status not in ('completed', 'failed');\r\n    update public.driver_runs set status = 'cancelled', updated_at = now()\r\n     where id = v_run.driver_run_id\r\n       and not exists (select 1 from public.driver_run_stops where run_id = v_run.driver_run_id);\r\n  end if;\r\n\r\n  select coalesce(max(stop_order), 0) into v_order\r\n    from public.driver_run_stops where run_id = v_driver_run_id;\r\n\r\n  for v_row in\r\n    select s.id, s.metadata, s.pickup_latitude, s.pickup_longitude,\r\n           cs.requested_start, cs.requested_end, cs.requested_flexible, cs.requested_at\r\n      from public.shipments s\r\n      left join public.collection_slots cs on cs.shipment_id = s.id\r\n     where s.collection_run_id = p_run_id\r\n       and s.deleted_at is null\r\n       and lower(coalesce(s.status, '')) in ('booking confirmed', 'confirmed', 'pending')\r\n       and not exists (\r\n         select 1 from public.driver_run_stops st\r\n          where st.run_id = v_driver_run_id and st.shipment_id = s.id)\r\n     -- Earliest promised window first; everyone without one after them.\r\n     order by cs.requested_start nulls last, s.created_at\r\n  loop\r\n    v_sender := coalesce(v_row.metadata->'sender', v_row.metadata->'senderDetails', '{}'::jsonb);\r\n    v_order := v_order + 1;\r\n\r\n    insert into public.driver_run_stops (\r\n      run_id, shipment_id, stop_order, stop_type, status, address, latitude, longitude,\r\n      recipient_name, time_window_start, time_window_end)\r\n    values (\r\n      v_driver_run_id, v_row.id, v_order, 'collection', 'planned',\r\n      nullif(btrim(concat_ws(', ',\r\n        nullif(v_sender->>'address', ''), nullif(v_sender->>'city', ''),\r\n        nullif(coalesce(v_sender->>'postalCode', v_sender->>'postcode'), ''))), ''),\r\n      v_row.pickup_latitude, v_row.pickup_longitude,\r\n      nullif(btrim(concat_ws(' ', v_sender->>'firstName', v_sender->>'lastName')), ''),\r\n      case when v_row.requested_start is null then null\r\n           else (v_run.collection_date + v_row.requested_start) at time zone 'UTC' end,\r\n      case when v_row.requested_end is null then null\r\n           else (v_run.collection_date + v_row.requested_end) at time zone 'UTC' end);\r\n\r\n    -- Honour the customer's own window as the dispatch window. Identical to\r\n    -- what they asked for, so this raises no \"moved\" flag and owes no call.\r\n    if v_row.requested_at is not null and not v_row.requested_flexible\r\n       and v_row.requested_start is not null then\r\n      update public.collection_slots\r\n         set dispatch_start = v_row.requested_start,\r\n             dispatch_end = v_row.requested_end,\r\n             dispatch_set_at = now(),\r\n             dispatch_set_by = auth.uid()\r\n       where shipment_id = v_row.id;\r\n    end if;\r\n\r\n    v_added := v_added + 1;\r\n  end loop;\r\n\r\n  update public.shipments set assigned_driver_id = p_driver_id\r\n   where collection_run_id = p_run_id and deleted_at is null\r\n     and lower(coalesce(status, '')) in ('booking confirmed', 'confirmed', 'pending');\r\n\r\n  update public.collection_runs\r\n     set driver_run_id = v_driver_run_id, status = 'active'\r\n   where id = p_run_id;\r\n\r\n  return jsonb_build_object(\r\n    'assigned', true, 'driverRunId', v_driver_run_id, 'stopsAdded', v_added,\r\n    'route', v_run.route, 'date', v_run.collection_date);\r\nend $$;\r\n\r\nrevoke all on function public.assign_collection_run_driver(uuid, uuid, text) from public, anon;\r\ngrant execute on function public.assign_collection_run_driver(uuid, uuid, text) to authenticated;\r\n\r\n/**\r\n * The drivers dispatch can put on a collection run.\r\n *\r\n * `stops_that_day` is what stops a dispatcher quietly double-booking someone:\r\n * a driver already carrying twenty stops on the 14th should look busy in the\r\n * picker, not identical to one carrying none. Delivery-only drivers are left\r\n * out — they work the Zimbabwe half.\r\n */\r\ncreate or replace function public.collection_drivers(p_date date default null)\r\nreturns table (\r\n  id uuid, full_name text, email text, driver_type text,\r\n  on_leave boolean, stops_that_day integer, run_route text)\r\nlanguage sql stable security definer set search_path = public as $$\r\n  select\r\n    p.id, p.full_name, p.email, coalesce(p.driver_type, 'both'), coalesce(p.on_leave, false),\r\n    coalesce((select count(*)::int from public.driver_run_stops st\r\n               join public.driver_runs r on r.id = st.run_id\r\n              where r.driver_id = p.id and r.run_date = p_date and r.status <> 'cancelled'), 0),\r\n    (select r.route_name from public.driver_runs r\r\n      where r.driver_id = p.id and r.run_date = p_date and r.status <> 'cancelled' limit 1)\r\n  from public.profiles p\r\n  where public.is_operations_admin()\r\n    and (lower(coalesce(p.role, '')) = 'driver' or p.is_admin = true\r\n         or lower(coalesce(p.role, '')) in ('admin', 'logistics'))\r\n    and coalesce(p.staff_active, true)\r\n    and coalesce(p.driver_type, 'both') <> 'delivery'\r\n  order by coalesce(p.on_leave, false), p.full_name\r\n$$;\r\n\r\nrevoke all on function public.collection_drivers(date) from public, anon;\r\ngrant execute on function public.collection_drivers(date) to authenticated;\r\n\n\n-- Booking confirmation, on the website and in the admin app.\r\n--\r\n-- Two things were inconsistent and this settles both.\r\n--\r\n-- 1. A booking made in the customer app landed as 'Booking Confirmed'; the same\r\n--    booking made on the website landed as 'pending'. The customer saw\r\n--    \"Booking Confirmed!\" on the receipt either way, so the website's own\r\n--    confirmation screen was contradicting the record behind it — and every\r\n--    staff view that groups by status put website bookings somewhere else.\r\n--    create_public_booking now writes the same status the app does.\r\n--\r\n-- 2. Admin can now confirm a shipment on the phone and lock its details\r\n--    (metadata.confirmation stamped, can_modify cleared). Nothing enforced\r\n--    that, so a customer could still edit an address after the confirmation\r\n--    call. update_customer_shipment now refuses, and it no longer writes the\r\n--    literal string 'To be confirmed' into a\r\n--    collection date that has none — the apps show the published route date\r\n--    instead, and a placeholder masquerading as data made that impossible.\r\n--\r\n-- Idempotent: safe to re-run.\r\n\r\ncreate or replace function public.create_public_booking(p jsonb)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_shipment public.shipments%rowtype;\r\n  v_payment_id uuid;\r\n  v_receipt_id uuid;\r\n  v_currency text := coalesce(nullif(p->>'currency', ''), 'GBP');\r\n  v_amount numeric := coalesce((p->>'amount')::numeric, 0);\r\n  v_tracking text := coalesce(nullif(p->>'trackingNumber', ''), 'ZSN' || lpad(floor(random() * 100000000)::text, 8, '0'));\r\n  v_receipt_no text := coalesce(nullif(p->>'receiptNumber', ''), 'RCP-' || lpad(floor(random() * 10000000000)::text, 10, '0'));\r\n  v_email text := lower(trim(coalesce(p->'metadata'->'sender'->>'email', '')));\r\nbegin\r\n  if v_amount < 0 then raise exception 'Booking amount cannot be negative'; end if;\r\n  if v_email = '' then raise exception 'A sender email address is required'; end if;\r\n  if v_currency not in ('GBP', 'EUR') then raise exception 'Unsupported currency %', v_currency; end if;\r\n\r\n  insert into public.shipments (\r\n    tracking_number, user_id, origin, destination, status, metadata,\r\n    collection_schedule_id, can_modify, can_cancel\r\n  ) values (\r\n    v_tracking,\r\n    -- A signed-in customer's booking is theirs; a guest booking is claimed\r\n    -- later by claim_guest_bookings() using the sender email above.\r\n    v_uid,\r\n    coalesce(p->>'origin', ''),\r\n    coalesce(p->>'destination', ''),\r\n    -- Same status the customer app's create_customer_booking writes, so a\r\n    -- booking means the same thing whichever door it came through.\r\n    'Booking Confirmed',\r\n    coalesce(p->'metadata', '{}'::jsonb),\r\n    nullif(p->>'collectionScheduleId', '')::uuid,\r\n    true, true\r\n  ) returning * into v_shipment;\r\n\r\n  insert into public.payments (\r\n    user_id, shipment_id, amount, currency, payment_method, payment_status, transaction_id\r\n  ) values (\r\n    v_uid, v_shipment.id, v_amount, v_currency,\r\n    coalesce(p->>'paymentMethod', 'standard'), 'pending',\r\n    coalesce(nullif(p->>'transactionId', ''), 'TX-' || lpad(floor(random() * 1000000000000)::text, 12, '0'))\r\n  ) returning id into v_payment_id;\r\n\r\n  insert into public.receipts (\r\n    user_id, shipment_id, payment_id, receipt_number, amount, currency, payment_method, status,\r\n    sender_details, recipient_details, shipment_details, payment_info, collection_info, payment_schedule\r\n  ) values (\r\n    v_uid, v_shipment.id, v_payment_id, v_receipt_no, v_amount, v_currency,\r\n    coalesce(p->>'paymentMethod', 'standard'), 'pending',\r\n    coalesce(p->'metadata'->'sender', '{}'::jsonb),\r\n    coalesce(p->'metadata'->'recipient', '{}'::jsonb),\r\n    coalesce(p->'metadata'->'items', '{}'::jsonb),\r\n    coalesce(p->'paymentInfo', '{}'::jsonb),\r\n    coalesce(p->'collectionInfo', '{}'::jsonb),\r\n    p->'paymentSchedule'\r\n  ) returning id into v_receipt_id;\r\n\r\n  return jsonb_build_object(\r\n    'shipmentId', v_shipment.id,\r\n    'trackingNumber', v_shipment.tracking_number,\r\n    'paymentId', v_payment_id,\r\n    'receiptId', v_receipt_id,\r\n    'receiptNumber', v_receipt_no,\r\n    'linkedToAccount', v_uid is not null\r\n  );\r\nend $$;\r\n\r\ngrant execute on function public.create_public_booking(jsonb) to anon, authenticated;\r\n\r\n-- Deliberately no backfill of existing 'pending' website bookings. Every staff\r\n-- view already reads the two as one queue, so rewriting historical rows would\r\n-- change live data for no gain. Ask if you want them brought across.\r\n\r\n-- Customers can correct the contact/address/date details of a booking until a\r\n-- driver has started collection *or* an admin has confirmed it on the phone.\r\n-- Otherwise identical to the version this replaces.\r\ncreate or replace function public.update_customer_shipment(p_shipment_id uuid, p jsonb) returns jsonb\r\nlanguage plpgsql security definer set search_path=public as $$\r\ndeclare v_ship public.shipments%rowtype; v_meta jsonb; v_schedule public.collection_schedules%rowtype;\r\nbegin\r\n  select * into v_ship from public.shipments where id=p_shipment_id and user_id=auth.uid() for update;\r\n  if not found then raise exception 'Shipment not found'; end if;\r\n  if lower(coalesce(v_ship.collection_status,'')) not in ('','awaiting collection')\r\n     or lower(coalesce(v_ship.driver_status,'')) in ('en_route','arrived','collected','completed') then\r\n    raise exception 'This shipment can no longer be edited because collection has started';\r\n  end if;\r\n  -- Admin has been through the booking with the customer and locked it. Keyed\r\n  -- on the confirmation stamp rather than can_modify, because that column\r\n  -- predates this schema and its default is not ours to assume. The message\r\n  -- names the reason: \"cannot be edited\" with no explanation sends the customer\r\n  -- to WhatsApp asking why.\r\n  if (v_ship.metadata->'confirmation'->>'confirmedAt') is not null then\r\n    raise exception 'This booking has been confirmed with you and is locked. Message us and we will make the change.';\r\n  end if;\r\n  if nullif(p->>'scheduleId','') is not null then\r\n    select * into v_schedule from public.collection_schedules where id=(p->>'scheduleId')::uuid;\r\n    if not found then raise exception 'Collection date not found'; end if;\r\n  end if;\r\n  v_meta := coalesce(v_ship.metadata,'{}'::jsonb);\r\n  v_meta := jsonb_set(v_meta,'{sender}',coalesce(p->'sender',v_meta->'sender'),true);\r\n  v_meta := jsonb_set(v_meta,'{recipient}',coalesce(p->'recipient',v_meta->'recipient'),true);\r\n  v_meta := jsonb_set(v_meta,'{collection}',jsonb_build_object(\r\n    -- No placeholder strings. An unassigned route and an unpublished date are\r\n    -- absent, not the words \"To be assigned\" and \"To be confirmed\" — the apps\r\n    -- now fill that gap with the published date for the route, which a\r\n    -- placeholder posing as data made impossible.\r\n    'route',coalesce(p->>'route',v_meta->'collection'->>'route'),\r\n    'date',coalesce(p->>'collectionDate',v_meta->'collection'->>'date'),\r\n    'scheduleId',nullif(p->>'scheduleId','')),true);\r\n  v_meta := jsonb_set(v_meta,'{pricing,paymentMethod}',to_jsonb(coalesce(p->>'paymentMethod',v_meta->'pricing'->>'paymentMethod','Bank Transfer')),true);\r\n  update public.shipments set\r\n    origin=coalesce(p->>'origin',origin), destination=coalesce(p->>'destination',destination),\r\n    collection_schedule_id=nullif(p->>'scheduleId','')::uuid,\r\n    metadata=v_meta, updated_at=now()\r\n  where id=p_shipment_id returning * into v_ship;\r\n  insert into public.audit_logs(user_id,action,entity_type,entity_id,details)\r\n  values(auth.uid(),'CUSTOMER_EDIT_BOOKING','SHIPMENT',p_shipment_id,p);\r\n  return jsonb_build_object('id',v_ship.id,'updatedAt',v_ship.updated_at);\r\nend $$;\r\ngrant execute on function public.update_customer_shipment(uuid,jsonb) to authenticated;\r\n\n\n-- An approved quote becomes one invoice line per item, not one lump.\r\n--\r\n-- The customer already lists their goods item by item, and an admin already\r\n-- prices each of those items separately in the staff app — `custom_quotes`\r\n-- carries the priced breakdown in `quote_items`. But booking off that quote\r\n-- collapsed the whole thing back into a single line:\r\n--\r\n--   Approved quote: Item 1: 3-seater sofa, Item 2: fridge freezer …   £1,850\r\n--\r\n-- which is what made the invoice and the delivery note hard to work from.\r\n-- Nobody loading a container can tick off one line covering nine things, and a\r\n-- customer querying a price has nothing to point at. The breakdown existed the\r\n-- whole time; this stops throwing it away.\r\n--\r\n-- Wraps rather than rewrites, exactly as the previous three revisions of this\r\n-- routine did — the pricing itself is untouched.\r\n--\r\n-- Idempotent: safe to re-run.\r\n\r\ndo $$ begin\r\n  if to_regprocedure('public.create_customer_booking_v3(jsonb)') is null then\r\n    execute 'alter function public.create_customer_booking(jsonb) rename to create_customer_booking_v3';\r\n  end if;\r\nend $$;\r\n\r\ncreate or replace function public.create_customer_booking(p jsonb) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_result jsonb;\r\n  v_quote_id uuid := nullif(p->>'quoteId', '')::uuid;\r\n  v_quote public.custom_quotes%rowtype;\r\n  v_shipment_id uuid;\r\n  v_ship public.shipments%rowtype;\r\n  v_invoice jsonb;\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_item jsonb;\r\n  v_itemised numeric := 0;\r\n  v_line jsonb;\r\n  v_replaced boolean := false;\r\nbegin\r\n  -- Everything the previous version did stays exactly as it was.\r\n  v_result := public.create_customer_booking_v3(p);\r\n  if v_quote_id is null then return v_result; end if;\r\n\r\n  select * into v_quote from public.custom_quotes where id = v_quote_id;\r\n  if not found or v_quote.quote_items is null or jsonb_array_length(v_quote.quote_items) = 0 then\r\n    return v_result;\r\n  end if;\r\n\r\n  -- Every item must carry its own price, and they must add up to the amount the\r\n  -- customer was quoted and agreed. If they do not, the single line stands:\r\n  -- silently re-pricing a booking to make a breakdown fit would be worse than\r\n  -- having no breakdown.\r\n  for v_item in select * from jsonb_array_elements(v_quote.quote_items) loop\r\n    if coalesce((v_item->>'amount')::numeric, 0) <= 0 then return v_result; end if;\r\n    v_itemised := v_itemised + (v_item->>'amount')::numeric;\r\n  end loop;\r\n  if abs(v_itemised - coalesce(v_quote.quoted_amount, -1)) > 0.01 then return v_result; end if;\r\n\r\n  v_shipment_id := (v_result->>'id')::uuid;\r\n  select * into v_ship from public.shipments where id = v_shipment_id for update;\r\n  if not found then return v_result; end if;\r\n\r\n  v_invoice := coalesce(v_ship.metadata->'invoice', '{}'::jsonb);\r\n\r\n  -- Swap the one \"Approved quote: …\" line for the priced breakdown, leaving\r\n  -- every other line (drums, seals, door delivery) exactly where it was.\r\n  for v_line in select * from jsonb_array_elements(coalesce(v_invoice->'items', '[]'::jsonb)) loop\r\n    if not v_replaced and coalesce(v_line->>'description', '') like 'Approved quote:%' then\r\n      v_replaced := true;\r\n      for v_item in select * from jsonb_array_elements(v_quote.quote_items) loop\r\n        v_lines := v_lines || jsonb_build_array(jsonb_build_object(\r\n          'description', left(coalesce(nullif(trim(v_item->>'description'), ''), 'Quoted item'), 200),\r\n          'quantity', 1,\r\n          'unitPrice', (v_item->>'amount')::numeric));\r\n      end loop;\r\n    else\r\n      v_lines := v_lines || jsonb_build_array(v_line);\r\n    end if;\r\n  end loop;\r\n  if not v_replaced then return v_result; end if;\r\n\r\n  v_invoice := jsonb_set(v_invoice, '{items}', v_lines, true);\r\n\r\n  update public.shipments\r\n     set metadata = jsonb_set(coalesce(metadata, '{}'::jsonb), '{invoice}', v_invoice, true),\r\n         updated_at = now()\r\n   where id = v_shipment_id;\r\n\r\n  return v_result || jsonb_build_object('invoice', v_invoice);\r\nend $$;\r\n\r\ngrant execute on function public.create_customer_booking(jsonb) to authenticated;\r\n\n\n-- Finance staff may attach a received proof to an existing customer's shipment.\r\n-- Customer uploads remain limited to their own account by the existing policy.\r\n\r\ndrop policy if exists \"Finance records customer payment proofs\" on public.payment_proofs;\r\ncreate policy \"Finance records customer payment proofs\" on public.payment_proofs\r\n  for insert to authenticated\r\n  with check (public.is_finance_staff());\r\n\r\ndrop policy if exists \"Finance uploads customer payment proofs\" on storage.objects;\r\ncreate policy \"Finance uploads customer payment proofs\" on storage.objects\r\n  for insert to authenticated\r\n  with check (bucket_id = 'payment-proofs' and public.is_finance_staff());\r\n\n\n-- A website booking gets the same customer reference as an app booking.\r\n--\r\n-- `create_customer_booking` has always stamped one — MAR09260013, from\r\n-- `next_customer_reference` — and the invoice and delivery note are numbered\r\n-- from it (INV-…, DN-…). `create_public_booking` never set the column at all,\r\n-- so a booking made on the website had no reference: staff screens fell back to\r\n-- a computed stand-in, and its documents had nothing stable to be numbered by.\r\n--\r\n-- Same generator, so the two doors produce references from one sequence and\r\n-- cannot collide.\r\n--\r\n-- Idempotent: safe to re-run. Existing rows are left alone — see the note at\r\n-- the end.\r\n\r\n-- The routine is SECURITY DEFINER, but a guest books as `anon`; granting\r\n-- execute keeps it callable if the search path is ever resolved as the caller.\r\ngrant execute on function public.next_customer_reference(text) to anon, authenticated;\r\n\r\ncreate or replace function public.create_public_booking(p jsonb)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_shipment public.shipments%rowtype;\r\n  v_payment_id uuid;\r\n  v_receipt_id uuid;\r\n  v_currency text := coalesce(nullif(p->>'currency', ''), 'GBP');\r\n  v_amount numeric := coalesce((p->>'amount')::numeric, 0);\r\n  v_tracking text := coalesce(nullif(p->>'trackingNumber', ''), 'ZSN' || lpad(floor(random() * 100000000)::text, 8, '0'));\r\n  v_receipt_no text := coalesce(nullif(p->>'receiptNumber', ''), 'RCP-' || lpad(floor(random() * 10000000000)::text, 10, '0'));\r\n  v_email text := lower(trim(coalesce(p->'metadata'->'sender'->>'email', '')));\r\n  v_name text;\r\n  v_reference text;\r\nbegin\r\n  if v_amount < 0 then raise exception 'Booking amount cannot be negative'; end if;\r\n  if v_email = '' then raise exception 'A sender email address is required'; end if;\r\n  if v_currency not in ('GBP', 'EUR') then raise exception 'Unsupported currency %', v_currency; end if;\r\n\r\n  -- Same three-letter prefix the app uses: the sender's own name.\r\n  v_name := trim(coalesce(p->'metadata'->'sender'->>'firstName', '') || ' '\r\n                 || coalesce(p->'metadata'->'sender'->>'lastName', ''));\r\n  if v_name = '' then v_name := coalesce(p->'metadata'->'sender'->>'name', ''); end if;\r\n  v_reference := public.next_customer_reference(v_name);\r\n\r\n  insert into public.shipments (\r\n    tracking_number, customer_reference, user_id, origin, destination, status, metadata,\r\n    collection_schedule_id, can_modify, can_cancel\r\n  ) values (\r\n    v_tracking,\r\n    v_reference,\r\n    -- A signed-in customer's booking is theirs; a guest booking is claimed\r\n    -- later by claim_guest_bookings() using the sender email above.\r\n    v_uid,\r\n    coalesce(p->>'origin', ''),\r\n    coalesce(p->>'destination', ''),\r\n    -- Same status the customer app's create_customer_booking writes, so a\r\n    -- booking means the same thing whichever door it came through.\r\n    'Booking Confirmed',\r\n    -- The reference is echoed into metadata as well, which is where the older\r\n    -- website admin screens read it from.\r\n    coalesce(p->'metadata', '{}'::jsonb) || jsonb_build_object(\r\n      'customerReference', v_reference,\r\n      'invoice', coalesce(p->'metadata'->'invoice', '{}'::jsonb)\r\n                 || jsonb_build_object('invoiceNumber', 'INV-' || v_reference),\r\n      'deliveryNote', jsonb_build_object('status', 'Draft', 'number', 'DN-' || v_reference)\r\n    ),\r\n    nullif(p->>'collectionScheduleId', '')::uuid,\r\n    true, true\r\n  ) returning * into v_shipment;\r\n\r\n  insert into public.payments (\r\n    user_id, shipment_id, amount, currency, payment_method, payment_status, transaction_id\r\n  ) values (\r\n    v_uid, v_shipment.id, v_amount, v_currency,\r\n    coalesce(p->>'paymentMethod', 'standard'), 'pending',\r\n    coalesce(nullif(p->>'transactionId', ''), 'TX-' || lpad(floor(random() * 1000000000000)::text, 12, '0'))\r\n  ) returning id into v_payment_id;\r\n\r\n  insert into public.receipts (\r\n    user_id, shipment_id, payment_id, receipt_number, amount, currency, payment_method, status,\r\n    sender_details, recipient_details, shipment_details, payment_info, collection_info, payment_schedule\r\n  ) values (\r\n    v_uid, v_shipment.id, v_payment_id, v_receipt_no, v_amount, v_currency,\r\n    coalesce(p->>'paymentMethod', 'standard'), 'pending',\r\n    coalesce(p->'metadata'->'sender', '{}'::jsonb),\r\n    coalesce(p->'metadata'->'recipient', '{}'::jsonb),\r\n    coalesce(p->'metadata'->'items', '{}'::jsonb),\r\n    coalesce(p->'paymentInfo', '{}'::jsonb),\r\n    coalesce(p->'collectionInfo', '{}'::jsonb),\r\n    p->'paymentSchedule'\r\n  ) returning id into v_receipt_id;\r\n\r\n  return jsonb_build_object(\r\n    'shipmentId', v_shipment.id,\r\n    'trackingNumber', v_shipment.tracking_number,\r\n    'customerReference', v_reference,\r\n    'paymentId', v_payment_id,\r\n    'receiptId', v_receipt_id,\r\n    'receiptNumber', v_receipt_no,\r\n    'linkedToAccount', v_uid is not null\r\n  );\r\nend $$;\r\n\r\ngrant execute on function public.create_public_booking(jsonb) to anon, authenticated;\r\n\r\n-- Existing website bookings keep whatever they have. Back-filling would mint a\r\n-- fresh reference for shipments customers were already given a tracking number\r\n-- for, and would renumber documents that may already be in someone's inbox.\r\n-- The staff apps compute a stable stand-in for those, so nothing is unlabelled.\r\n\n\n-- Verified addresses, so a driver is never sent to a guess.\n--\n-- Geocoding cannot reach every booking. Roughly 40% of live shipments carry a\n-- postcode, and Irish addresses carry no Eircode at all — \"Irish Bar Church\n-- Street Tullow, Cork\" is a real pickup. Those resolve, at best, to a town\n-- centroid, which is fine for grouping a day's work on a map and useless for\n-- driving to a door.\n--\n-- So a point has a *precision*, and a human has the last word:\n--   exact       — a UK postcode centroid or a street-level match\n--   approximate — a town centroid; the driver sees a warning\n--   manual      — placed or corrected by admin; always treated as exact\n--   null        — never geocoded\n--\n-- Verification is separate from precision: an admin confirming the address is\n-- right is a different claim from the geocoder being confident, and the driver\n-- app shows a banner until someone has made the first claim. Per the agreed\n-- scope an unverified address warns but never blocks — drivers keep working\n-- while admin catches up.\n\nalter table public.shipments\n  add column if not exists pickup_address_verified boolean not null default false,\n  add column if not exists pickup_address_verified_at timestamptz,\n  add column if not exists pickup_address_verified_by uuid references auth.users(id) on delete set null,\n  add column if not exists pickup_geocode_precision text,\n  add column if not exists delivery_latitude double precision,\n  add column if not exists delivery_longitude double precision,\n  add column if not exists delivery_address_verified boolean not null default false,\n  add column if not exists delivery_address_verified_at timestamptz,\n  add column if not exists delivery_address_verified_by uuid references auth.users(id) on delete set null,\n  add column if not exists delivery_geocode_precision text;\n\ndo $$\nbegin\n  if not exists (\n    select 1 from pg_constraint where conname = 'shipments_pickup_geocode_precision_check'\n  ) then\n    alter table public.shipments add constraint shipments_pickup_geocode_precision_check\n      check (pickup_geocode_precision is null\n             or pickup_geocode_precision in ('exact', 'approximate', 'manual'));\n  end if;\n  if not exists (\n    select 1 from pg_constraint where conname = 'shipments_delivery_geocode_precision_check'\n  ) then\n    alter table public.shipments add constraint shipments_delivery_geocode_precision_check\n      check (delivery_geocode_precision is null\n             or delivery_geocode_precision in ('exact', 'approximate', 'manual'));\n  end if;\nend $$;\n\n-- The driver's route query asks \"today's collections that have a point\"; the\n-- admin's cleanup queue asks the opposite. One partial index serves both.\ncreate index if not exists shipments_pickup_point_idx\n  on public.shipments (pickup_latitude, pickup_longitude)\n  where deleted_at is null;\n\ncreate index if not exists shipments_pickup_unverified_idx\n  on public.shipments (pickup_address_verified)\n  where deleted_at is null and pickup_address_verified = false;\n\n/**\n * Admin confirms an address, and may place the point by hand.\n *\n * Passing coordinates marks the precision 'manual', which is what makes this\n * usable for the addresses no geocoder will ever resolve: someone looks the\n * place up, drops the pin, and the driver can navigate to it like any other.\n * Passing no coordinates just records the human check against whatever the\n * geocoder found.\n */\ncreate or replace function public.set_shipment_address_verification(\n  p_shipment_id uuid,\n  p_which text,\n  p_verified boolean default true,\n  p_latitude double precision default null,\n  p_longitude double precision default null\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_which text := lower(coalesce(p_which, 'pickup'));\n  v_has_point boolean := p_latitude is not null and p_longitude is not null;\n  v_row public.shipments%rowtype;\nbegin\n  if not (public.is_operations_admin() or public.is_finance_staff()) then\n    raise exception 'Only admin or finance can verify an address'\n      using errcode = '42501';\n  end if;\n\n  if v_which not in ('pickup', 'delivery') then\n    raise exception 'p_which must be pickup or delivery, got %', p_which\n      using errcode = '22023';\n  end if;\n\n  -- Guard the point before it is written: a swapped lat/lng, or a zero pair\n  -- from an empty form, would put a driver in the Atlantic.\n  if v_has_point and (p_latitude < -90 or p_latitude > 90 or p_longitude < -180 or p_longitude > 180) then\n    raise exception 'Coordinates out of range: %, %', p_latitude, p_longitude\n      using errcode = '22023';\n  end if;\n  if v_has_point and p_latitude = 0 and p_longitude = 0 then\n    raise exception 'Refusing to save a null island coordinate'\n      using errcode = '22023';\n  end if;\n\n  if v_which = 'pickup' then\n    update public.shipments set\n      pickup_address_verified = coalesce(p_verified, true),\n      pickup_address_verified_at = case when coalesce(p_verified, true) then now() else null end,\n      pickup_address_verified_by = case when coalesce(p_verified, true) then auth.uid() else null end,\n      pickup_latitude = case when v_has_point then p_latitude else pickup_latitude end,\n      pickup_longitude = case when v_has_point then p_longitude else pickup_longitude end,\n      pickup_geocode_precision = case when v_has_point then 'manual' else pickup_geocode_precision end,\n      updated_at = now()\n    where id = p_shipment_id\n    returning * into v_row;\n  else\n    update public.shipments set\n      delivery_address_verified = coalesce(p_verified, true),\n      delivery_address_verified_at = case when coalesce(p_verified, true) then now() else null end,\n      delivery_address_verified_by = case when coalesce(p_verified, true) then auth.uid() else null end,\n      delivery_latitude = case when v_has_point then p_latitude else delivery_latitude end,\n      delivery_longitude = case when v_has_point then p_longitude else delivery_longitude end,\n      delivery_geocode_precision = case when v_has_point then 'manual' else delivery_geocode_precision end,\n      updated_at = now()\n    where id = p_shipment_id\n    returning * into v_row;\n  end if;\n\n  if v_row.id is null then\n    raise exception 'Shipment % not found', p_shipment_id using errcode = 'P0002';\n  end if;\n\n  return jsonb_build_object(\n    'id', v_row.id,\n    'which', v_which,\n    'verified', case when v_which = 'pickup' then v_row.pickup_address_verified else v_row.delivery_address_verified end,\n    'latitude', case when v_which = 'pickup' then v_row.pickup_latitude else v_row.delivery_latitude end,\n    'longitude', case when v_which = 'pickup' then v_row.pickup_longitude else v_row.delivery_longitude end,\n    'precision', case when v_which = 'pickup' then v_row.pickup_geocode_precision else v_row.delivery_geocode_precision end\n  );\nend $$;\n\nrevoke all on function public.set_shipment_address_verification(uuid, text, boolean, double precision, double precision) from public, anon;\ngrant execute on function public.set_shipment_address_verification(uuid, text, boolean, double precision, double precision) to authenticated;\n\n/**\n * Editing an address invalidates the verification that was made against the\n * old one.\n *\n * Without this a verified pin survives an address change and the driver is\n * confidently routed to the previous house. The point is cleared too, so the\n * geocoder picks the row up again on its next pass.\n */\ncreate or replace function public.reset_address_verification_on_change()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare\n  old_pickup text := lower(trim(coalesce(\n    old.metadata->'sender'->>'address', old.metadata->'senderDetails'->>'address', '')));\n  new_pickup text := lower(trim(coalesce(\n    new.metadata->'sender'->>'address', new.metadata->'senderDetails'->>'address', '')));\n  old_drop text := lower(trim(coalesce(\n    old.metadata->'recipient'->>'address', old.metadata->'recipientDetails'->>'address', '')));\n  new_drop text := lower(trim(coalesce(\n    new.metadata->'recipient'->>'address', new.metadata->'recipientDetails'->>'address', '')));\nbegin\n  if new_pickup is distinct from old_pickup then\n    new.pickup_address_verified := false;\n    new.pickup_address_verified_at := null;\n    new.pickup_address_verified_by := null;\n    new.pickup_latitude := null;\n    new.pickup_longitude := null;\n    new.pickup_geocode_precision := null;\n  end if;\n\n  if new_drop is distinct from old_drop then\n    new.delivery_address_verified := false;\n    new.delivery_address_verified_at := null;\n    new.delivery_address_verified_by := null;\n    new.delivery_latitude := null;\n    new.delivery_longitude := null;\n    new.delivery_geocode_precision := null;\n  end if;\n\n  return new;\nend $$;\n\ndrop trigger if exists shipments_reset_address_verification on public.shipments;\ncreate trigger shipments_reset_address_verification\n  before update of metadata on public.shipments\n  for each row\n  execute function public.reset_address_verification_on_change();\n\n\n-- Drivers start their own routes.\n--\n-- The run/stop engine already does everything a collection day needs — status\n-- transitions, arrivals, scanning, seals, offline replay — but nothing has\n-- created a run since the dispatcher board was retired, so all of it has sat\n-- idle with zero rows. These two routines give the driver the one thing\n-- dispatch used to provide: a run to work through.\n--\n-- `driver_runs` is unique on (driver_id, run_date), so a run is *the driver's\n-- day*, not a single route. Starting a second route appends its collections to\n-- the same run, which is what happens in practice when a short route finishes\n-- early and the driver picks up another.\n\n/**\n * Start (or resume) today's run and add a route's collections to it.\n *\n * Shipments arrive in the order the driver should drive them — the optimiser\n * has already run on the phone — and are appended after whatever is already on\n * the run. Re-starting a route the driver is already working is a no-op for\n * the stops that exist, so tapping it twice cannot duplicate a collection.\n */\ncreate or replace function public.start_collection_route(\n  p_route_name text,\n  p_shipment_ids uuid[],\n  p_date date default null\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_driver uuid := auth.uid();\n  v_date date := coalesce(p_date, current_date);\n  v_run_id uuid;\n  v_next integer;\n  v_added integer := 0;\n  v_shipment uuid;\nbegin\n  if v_driver is null then\n    raise exception 'Sign in required' using errcode = '42501';\n  end if;\n\n  -- A driver may only start their own run. Admins get in for support.\n  if not (public.is_staff_member() or public.is_operations_admin()) then\n    raise exception 'Staff access required' using errcode = '42501';\n  end if;\n\n  insert into public.driver_runs as r (driver_id, run_date, status, route_name, run_type, started_at)\n  values (v_driver, v_date, 'active', nullif(trim(coalesce(p_route_name, '')), ''), 'pickup', now())\n  on conflict (driver_id, run_date) do update\n    set status = case when r.status in ('completed', 'cancelled') then r.status else 'active' end,\n        -- Keep the first route's name when a second is appended, rather than\n        -- silently relabelling the day.\n        route_name = coalesce(r.route_name, excluded.route_name),\n        started_at = coalesce(r.started_at, now()),\n        updated_at = now()\n  returning r.id into v_run_id;\n\n  select coalesce(max(stop_order), 0) + 1 into v_next\n  from public.driver_run_stops where run_id = v_run_id;\n\n  -- foreach preserves the caller's order, which is the optimised order.\n  foreach v_shipment in array coalesce(p_shipment_ids, array[]::uuid[])\n  loop\n    -- Already on this run? Leave it exactly as it is; it may be half worked.\n    if exists (\n      select 1 from public.driver_run_stops\n      where run_id = v_run_id and shipment_id = v_shipment\n    ) then\n      continue;\n    end if;\n\n    insert into public.driver_run_stops (\n      run_id, shipment_id, stop_order, stop_type, status, address, latitude, longitude\n    )\n    select\n      v_run_id,\n      s.id,\n      v_next,\n      'collection',\n      'planned',\n      coalesce(\n        s.metadata->'sender'->>'address',\n        s.metadata->'senderDetails'->>'address'\n      ),\n      s.pickup_latitude,\n      s.pickup_longitude\n    from public.shipments s\n    where s.id = v_shipment and s.deleted_at is null;\n\n    if found then\n      v_next := v_next + 1;\n      v_added := v_added + 1;\n    end if;\n  end loop;\n\n  return jsonb_build_object(\n    'runId', v_run_id,\n    'date', v_date,\n    'added', v_added,\n    'stops', (\n      select coalesce(jsonb_agg(jsonb_build_object(\n        'stopId', st.id,\n        'shipmentId', st.shipment_id,\n        'stopOrder', st.stop_order,\n        'status', st.status\n      ) order by st.stop_order), '[]'::jsonb)\n      from public.driver_run_stops st where st.run_id = v_run_id\n    )\n  );\nend $$;\n\nrevoke all on function public.start_collection_route(text, uuid[], date) from public, anon;\ngrant execute on function public.start_collection_route(text, uuid[], date) to authenticated;\n\n/**\n * Reorder the stops a driver has not finished yet.\n *\n * Only outstanding work moves. Completed and failed stops keep the positions\n * they were actually worked in, because the run doubles as the record of what\n * happened and rewriting history would make the day's audit trail a fiction.\n * The reordered stops are numbered after them.\n */\ncreate or replace function public.reorder_driver_stops(\n  p_run_id uuid,\n  p_stop_ids uuid[]\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_driver uuid;\n  v_done integer;\n  v_index integer := 0;\n  v_stop uuid;\n  v_moved integer := 0;\nbegin\n  select driver_id into v_driver from public.driver_runs where id = p_run_id;\n  if v_driver is null then\n    raise exception 'Run % not found', p_run_id using errcode = 'P0002';\n  end if;\n  if v_driver <> auth.uid() and not public.is_operations_admin() then\n    raise exception 'That is not your run' using errcode = '42501';\n  end if;\n\n  select count(*) into v_done\n  from public.driver_run_stops\n  where run_id = p_run_id and status in ('completed', 'failed');\n\n  -- Two passes, because stop_order has no unique constraint but sharing a\n  -- number would still make the driver's list order arbitrary. Park the moving\n  -- stops well clear of the finished ones first.\n  update public.driver_run_stops\n     set stop_order = stop_order + 100000\n   where run_id = p_run_id and status not in ('completed', 'failed');\n\n  foreach v_stop in array coalesce(p_stop_ids, array[]::uuid[])\n  loop\n    v_index := v_index + 1;\n    update public.driver_run_stops\n       set stop_order = v_done + v_index, updated_at = now()\n     where id = v_stop\n       and run_id = p_run_id\n       and status not in ('completed', 'failed');\n    if found then v_moved := v_moved + 1; end if;\n  end loop;\n\n  -- Anything the caller did not mention (a stop added on another device, say)\n  -- keeps a stable position at the end rather than colliding on a number.\n  with stragglers as (\n    select id, row_number() over (order by stop_order) as rn\n    from public.driver_run_stops\n    where run_id = p_run_id and stop_order > 100000\n  )\n  update public.driver_run_stops st\n     set stop_order = v_done + v_index + s.rn\n    from stragglers s\n   where st.id = s.id;\n\n  -- Finished stops are renumbered 1..n in the order they were worked, so the\n  -- list reads chronologically from the top.\n  with worked as (\n    select id, row_number() over (\n      order by coalesce(completed_at, failed_at, arrived_at, created_at)\n    ) as rn\n    from public.driver_run_stops\n    where run_id = p_run_id and status in ('completed', 'failed')\n  )\n  update public.driver_run_stops st\n     set stop_order = w.rn\n    from worked w\n   where st.id = w.id;\n\n  return jsonb_build_object('runId', p_run_id, 'moved', v_moved, 'completed', v_done);\nend $$;\n\nrevoke all on function public.reorder_driver_stops(uuid, uuid[]) from public, anon;\ngrant execute on function public.reorder_driver_stops(uuid, uuid[]) to authenticated;\n\n/**\n * A driver's own run for a date, with its stops joined to what the driver\n * needs at the door.\n *\n * One read, so the route screen does not fan out into a query per stop.\n */\ncreate or replace function public.driver_run_for_date(p_date date default null)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce(\n    (select jsonb_build_object(\n       'runId', r.id,\n       'routeName', r.route_name,\n       'status', r.status,\n       'date', r.run_date,\n       'startedAt', r.started_at,\n       'stops', coalesce((\n         select jsonb_agg(jsonb_build_object(\n           'stopId', st.id,\n           'shipmentId', st.shipment_id,\n           'stopOrder', st.stop_order,\n           'status', st.status,\n           'address', st.address,\n           'latitude', st.latitude,\n           'longitude', st.longitude,\n           'arrivedAt', st.arrived_at,\n           'completedAt', st.completed_at,\n           'customerReference', s.customer_reference,\n           'trackingNumber', s.tracking_number,\n           'customerName', coalesce(\n             s.metadata->'sender'->>'name',\n             trim(concat_ws(' ',\n               s.metadata->'sender'->>'firstName',\n               s.metadata->'sender'->>'lastName'))),\n           'phone', s.metadata->'sender'->>'phone',\n           'addressVerified', s.pickup_address_verified,\n           'geocodePrecision', s.pickup_geocode_precision\n         ) order by st.stop_order)\n         from public.driver_run_stops st\n         join public.shipments s on s.id = st.shipment_id\n         where st.run_id = r.id\n       ), '[]'::jsonb)\n     )\n     from public.driver_runs r\n     where r.driver_id = auth.uid()\n       and r.run_date = coalesce(p_date, current_date)\n     limit 1),\n    'null'::jsonb\n  );\n$$;\n\nrevoke all on function public.driver_run_for_date(date) from public, anon;\ngrant execute on function public.driver_run_for_date(date) to authenticated;\n\n\n-- The collection itself: identity at the door, the invoice, and the lock.\n--\n-- Three rules from the agreed flow that the existing routines got wrong:\n--\n--   1. Identity is QR *or* PIN, never both. complete_driver_handover demanded a\n--      scanned QR **and** a matching six-digit code, so a customer whose phone\n--      was flat could not be collected from at all. Scanning proves the driver\n--      is at the right shipment; the code proves it when there is nothing to\n--      scan. Either is enough, neither alone is optional.\n--\n--   2. Photos are optional. The routine refused to complete a collection\n--      without a 'pickup_departure' photo, which is a hard block on a driver\n--      whose camera or storage fails, for evidence that is nice to have rather\n--      than required.\n--\n--   3. Drivers may correct the whole invoice, not just the wording. The old\n--      routine locked quantity and price (\"Drivers may correct the wording\n--      only\"), which leaves the invoice wrong whenever the goods at the door\n--      differ from the booking - the exact case the driver is there to catch.\n--      They may now change descriptions, quantities, prices, add and remove\n--      lines, and record what was actually paid.\n--\n-- What replaces the old locks is a real one: once the driver confirms, the\n-- invoice is closed to them for good. Admin and finance can still edit it.\n\n-- ---------------------------------------------------------------------------\n-- A. Every booking starts with a draft invoice and a draft delivery note\n-- ---------------------------------------------------------------------------\n\n/**\n * A booking is not just a shipment: it is an invoice waiting to be confirmed\n * and a delivery note waiting to be filled in. Creating both up front is what\n * lets the website, the staff app and the customer all show the same paperwork\n * from the moment the booking is confirmed.\n *\n * Deliberately a trigger rather than an edit to each booking routine: bookings\n * arrive from the website, the customer app and manual admin entry, and only a\n * trigger catches all three (and anything added later).\n *\n * A quote that already priced the job keeps its invoice untouched. No due date\n * is invented — an invented one would make the invoice read \"overdue\" on a day\n * nobody chose.\n */\ncreate or replace function public.ensure_booking_paperwork()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare\n  v_invoice jsonb := new.metadata->'invoice';\n  v_currency text;\n  v_amount numeric;\nbegin\n  if v_invoice is null or jsonb_typeof(v_invoice) <> 'object' then\n    -- Ireland prices in euro, everywhere else in pounds. `origin` carries\n    -- trailing spaces on live rows, hence the trim.\n    v_currency := case\n      when lower(trim(coalesce(new.origin, ''))) in ('ireland', 'republic of ireland', 'eire')\n        then 'EUR' else 'GBP' end;\n\n    v_amount := coalesce(\n      (new.metadata->'pricing'->>'finalAmount')::numeric,\n      (new.metadata->'pricing'->>'total')::numeric,\n      (new.metadata->>'quotedAmount')::numeric,\n      0);\n\n    new.metadata := coalesce(new.metadata, '{}'::jsonb) || jsonb_build_object(\n      'invoice', jsonb_build_object(\n        'invoiceNumber', 'INV-' || to_char(now(), 'YYYYMMDD') || '-' ||\n                         upper(substr(replace(new.id::text, '-', ''), 1, 6)),\n        'issueDate', to_char(now(), 'YYYY-MM-DD'),\n        'currency', v_currency,\n        'items', case when v_amount > 0 then jsonb_build_array(jsonb_build_object(\n                        'description', 'Shipping and collection service',\n                        'quantity', 1,\n                        'unitPrice', v_amount))\n                 else '[]'::jsonb end,\n        'discount', 0,\n        'taxRate', 0,\n        'payments', '[]'::jsonb,\n        'createdAt', to_char(now(), 'YYYY-MM-DD\"T\"HH24:MI:SSOF')\n      ));\n  end if;\n\n  if new.delivery_note_status is null then\n    new.delivery_note_status := 'Draft';\n  end if;\n\n  return new;\nend $$;\n\ndrop trigger if exists shipments_ensure_booking_paperwork on public.shipments;\ncreate trigger shipments_ensure_booking_paperwork\n  before insert on public.shipments\n  for each row\n  execute function public.ensure_booking_paperwork();\n\n-- ---------------------------------------------------------------------------\n-- A2. Opening the shipment with the code instead of the scan\n-- ---------------------------------------------------------------------------\n\n-- The QR scan already had somewhere to record itself; the code did not, so the\n-- app could only ever unlock a stop by scanning. This is the code's equivalent.\nalter table public.driver_run_stops\n  add column if not exists code_verified_at timestamptz;\n\n/**\n * Open the shipment by the six-digit code from the customer's app.\n *\n * The counterpart to verify_driver_stop_qr, for the customer whose phone is\n * flat, who cannot find the QR, or who reads the code out over the phone\n * because they had to leave a neighbour with the parcels.\n */\ncreate or replace function public.verify_driver_stop_code(\n  p_stop_id uuid,\n  p_code text\n) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  v_stop public.driver_run_stops%rowtype;\n  v_run public.driver_runs%rowtype;\n  v_ship public.shipments%rowtype;\n  v_expected text;\n  v_code text := trim(coalesce(p_code, ''));\nbegin\n  select * into v_stop from public.driver_run_stops where id = p_stop_id;\n  if not found then raise exception 'Stop not found'; end if;\n  select * into v_run from public.driver_runs where id = v_stop.run_id;\n  if v_run.driver_id <> auth.uid() and not public.is_operations_admin() then\n    raise exception 'Stop is not assigned to you' using errcode = '42501';\n  end if;\n\n  select * into v_ship from public.shipments where id = v_stop.shipment_id;\n  v_expected := case when v_stop.stop_type = 'collection'\n                     then v_ship.collection_code else v_ship.delivery_code end;\n\n  if v_expected is null then\n    raise exception 'This shipment has no handover code. Scan the customer QR code instead.';\n  end if;\n  if v_code <> v_expected then\n    raise exception 'That code does not match this shipment';\n  end if;\n\n  update public.driver_run_stops\n     set code_verified_at = now(), updated_at = now()\n   where id = v_stop.id;\n\n  return jsonb_build_object('stopId', v_stop.id, 'verified', true, 'method', 'code');\nend $$;\n\ngrant execute on function public.verify_driver_stop_code(uuid, text) to authenticated;\n\n-- ---------------------------------------------------------------------------\n-- B. The driver's invoice\n-- ---------------------------------------------------------------------------\n\n/**\n * Save, and optionally confirm, the invoice for a collection.\n *\n * `p_confirm` is the point of no return for the driver: it stamps\n * driverConfirmedAt, and every later call from a driver is refused. Admin and\n * finance keep full access, because a confirmed invoice still has to be\n * correctable when a customer disputes it.\n *\n * Money taken at the door is appended to metadata.invoice.payments, which is\n * where every other surface already reads it from — so paid / partially paid\n * follows automatically on the customer's app, the admin dashboard, finance\n * and the website, with no second source of truth to keep in step.\n */\ncreate or replace function public.create_driver_invoice(\n  p_stop_id uuid,\n  p_line_items jsonb,\n  p_discount numeric default 0,\n  p_tax_rate numeric default 0,\n  p_currency text default 'GBP',\n  p_notes text default null,\n  p_amount_paid numeric default null,\n  p_payment_method text default null,\n  p_confirm boolean default false\n) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  v_stop public.driver_run_stops%rowtype;\n  v_run public.driver_runs%rowtype;\n  v_ship public.shipments%rowtype;\n  v_invoice public.driver_invoices%rowtype;\n  v_meta_invoice jsonb;\n  v_items jsonb;\n  v_payments jsonb;\n  v_discount numeric;\n  v_tax_rate numeric;\n  v_currency text;\n  v_subtotal numeric := 0;\n  v_tax numeric := 0;\n  v_total numeric := 0;\n  v_number text;\n  v_is_staff boolean := public.is_operations_admin() or public.is_finance_staff();\nbegin\n  select * into v_stop from public.driver_run_stops where id = p_stop_id;\n  if not found then raise exception 'Stop not found'; end if;\n  select * into v_run from public.driver_runs where id = v_stop.run_id;\n  if not v_is_staff and (v_run.driver_id <> auth.uid() or v_stop.stop_type <> 'collection') then\n    raise exception 'Pickup driver access required';\n  end if;\n  if v_stop.status <> 'arrived' and not v_is_staff then\n    raise exception 'Mark the collection as arrived first';\n  end if;\n\n  select * into v_ship from public.shipments where id = v_stop.shipment_id for update;\n  v_meta_invoice := coalesce(v_ship.metadata->'invoice', '{}'::jsonb);\n\n  -- The lock. Confirmed is confirmed.\n  if not v_is_staff and nullif(v_meta_invoice->>'driverConfirmedAt', '') is not null then\n    raise exception 'This invoice was confirmed and can no longer be changed. Ask admin or finance to amend it.'\n      using errcode = '42501';\n  end if;\n\n  if jsonb_typeof(p_line_items) <> 'array' or jsonb_array_length(p_line_items) = 0 then\n    raise exception 'Add at least one invoice item';\n  end if;\n\n  -- Normalise every line, so a missing quantity cannot silently zero a price.\n  select coalesce(jsonb_agg(jsonb_build_object(\n           'description', coalesce(nullif(trim(x->>'description'), ''), 'Item'),\n           'quantity', greatest(0, coalesce((x->>'quantity')::numeric, 1)),\n           'unitPrice', greatest(0, coalesce((x->>'unitPrice')::numeric, 0)))), '[]'::jsonb)\n    into v_items\n    from jsonb_array_elements(p_line_items) x;\n\n  v_discount := greatest(0, coalesce(p_discount, 0));\n  v_tax_rate := greatest(0, coalesce(p_tax_rate, 0));\n  v_currency := upper(coalesce(nullif(trim(p_currency), ''), v_meta_invoice->>'currency', 'GBP'));\n\n  select coalesce(sum(coalesce((x->>'quantity')::numeric, 0) * coalesce((x->>'unitPrice')::numeric, 0)), 0)\n    into v_subtotal from jsonb_array_elements(v_items) x;\n  v_tax := greatest(0, v_subtotal - v_discount) * v_tax_rate / 100;\n  v_total := greatest(0, v_subtotal - v_discount) + v_tax;\n\n  v_number := coalesce(nullif(v_meta_invoice->>'invoiceNumber', ''),\n                       'INV-' || to_char(now(), 'YYYYMMDD') || '-' ||\n                       upper(substr(replace(v_stop.id::text, '-', ''), 1, 6)));\n\n  -- Money taken at the door, appended rather than replaced: a part payment now\n  -- and another later are two entries, and the running total is their sum.\n  v_payments := coalesce(v_meta_invoice->'payments', '[]'::jsonb);\n  if coalesce(p_amount_paid, 0) > 0 then\n    v_payments := v_payments || jsonb_build_array(jsonb_build_object(\n      'amount', p_amount_paid,\n      'method', coalesce(nullif(trim(p_payment_method), ''), 'Cash on collection'),\n      'date', to_char(now(), 'YYYY-MM-DD'),\n      'recordedBy', 'driver'));\n  end if;\n\n  insert into public.driver_invoices(\n    shipment_id, stop_id, driver_id, invoice_number, currency,\n    line_items, subtotal, discount, tax, total, notes)\n  values (v_stop.shipment_id, v_stop.id, coalesce(v_run.driver_id, auth.uid()), v_number, v_currency,\n          v_items, v_subtotal, v_discount, v_tax, v_total, p_notes)\n  on conflict (stop_id) do update set\n    line_items = excluded.line_items, subtotal = excluded.subtotal,\n    discount = excluded.discount, tax = excluded.tax, total = excluded.total,\n    currency = excluded.currency, notes = excluded.notes, updated_at = now()\n  returning * into v_invoice;\n\n  v_meta_invoice := v_meta_invoice || jsonb_build_object(\n    'invoiceNumber', v_invoice.invoice_number,\n    'issueDate', coalesce(v_meta_invoice->>'issueDate', to_char(now(), 'YYYY-MM-DD')),\n    'items', v_items,\n    'discount', v_discount,\n    'taxRate', v_tax_rate,\n    'currency', v_currency,\n    'payments', v_payments,\n    'notes', coalesce(p_notes, v_meta_invoice->>'notes'));\n\n  if p_confirm then\n    v_meta_invoice := v_meta_invoice || jsonb_build_object(\n      'driverConfirmedAt', to_char(now(), 'YYYY-MM-DD\"T\"HH24:MI:SSOF'),\n      'driverConfirmedBy', auth.uid(),\n      -- sentAt is what moves it out of \"draft\" for every reader.\n      'sentAt', coalesce(v_meta_invoice->>'sentAt', to_char(now(), 'YYYY-MM-DD\"T\"HH24:MI:SSOF')));\n  end if;\n\n  update public.shipments\n     set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('invoice', v_meta_invoice),\n         updated_at = now()\n   where id = v_stop.shipment_id;\n\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\n  values (auth.uid(), case when p_confirm then 'DRIVER_INVOICE_CONFIRM' else 'DRIVER_INVOICE_SAVE' end,\n          'DRIVER_INVOICE', v_invoice.id,\n          jsonb_build_object('stopId', v_stop.id, 'total', v_total,\n                             'paid', coalesce(p_amount_paid, 0), 'confirmed', p_confirm));\n\n  return to_jsonb(v_invoice) || jsonb_build_object('confirmed', p_confirm, 'invoice', v_meta_invoice);\nend $$;\n\ngrant execute on function public.create_driver_invoice(uuid, jsonb, numeric, numeric, text, text, numeric, text, boolean) to authenticated;\n\n-- ---------------------------------------------------------------------------\n-- C. Completing the stop\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.complete_driver_handover(\n  p_stop_id uuid,\n  p_customer_code text default null,\n  p_notes text default null\n) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  v_stop public.driver_run_stops%rowtype;\n  v_run public.driver_runs%rowtype;\n  v_ship public.shipments%rowtype;\n  v_now timestamptz := now();\n  v_proofs int := 0;\n  v_note text;\n  v_code text := trim(coalesce(p_customer_code, ''));\n  v_scanned boolean;\n  v_expected text;\nbegin\n  select * into v_stop from public.driver_run_stops where id = p_stop_id for update;\n  if not found then raise exception 'Stop not found'; end if;\n  select * into v_run from public.driver_runs where id = v_stop.run_id;\n  if v_run.driver_id <> auth.uid() then raise exception 'Stop is not assigned to you'; end if;\n  if v_stop.status <> 'arrived' then raise exception 'Mark the stop as arrived first'; end if;\n\n  select * into v_ship from public.shipments where id = v_stop.shipment_id for update;\n  select count(*) into v_proofs from public.driver_proofs where stop_id = v_stop.id;\n\n  -- Identity: the scan or the code, whichever the customer could manage.\n  -- A code already checked when the shipment was opened counts, so the driver\n  -- is not asked for the same six digits twice.\n  v_scanned := v_stop.qr_verified_at is not null or v_stop.code_verified_at is not null;\n  v_expected := case when v_stop.stop_type = 'collection'\n                     then v_ship.collection_code else v_ship.delivery_code end;\n\n  if not v_scanned then\n    if v_code = '' then\n      raise exception 'Scan the customer QR code, or enter the six-digit code from their app';\n    end if;\n    if v_expected is null or v_code <> v_expected then\n      raise exception 'That code does not match this shipment';\n    end if;\n  end if;\n\n  if v_stop.stop_type = 'collection' then\n    -- The invoice must be confirmed, not merely drafted: confirming it is the\n    -- driver agreeing what was collected and what was paid.\n    if nullif(v_ship.metadata->'invoice'->>'driverConfirmedAt', '') is null then\n      raise exception 'Confirm the invoice before completing the collection';\n    end if;\n    update public.shipments\n       set status = 'Collected', driver_status = 'collected',\n           collected_at = v_now, collected_by = auth.uid(), updated_at = v_now\n     where id = v_ship.id;\n  else\n    v_note := 'DN-' || to_char(now(), 'YYYYMMDD') || '-' ||\n              upper(substr(replace(v_stop.id::text, '-', ''), 1, 6));\n    insert into public.delivery_notes(\n      shipment_id, stop_id, driver_id, note_number, delivery_address,\n      delivered_at, customer_code_verified, proof_count, notes, status)\n    values (v_ship.id, v_stop.id, auth.uid(), v_note, v_stop.address,\n            v_now, true, v_proofs, p_notes, 'completed')\n    on conflict (stop_id) do update set\n      delivered_at = v_now, customer_code_verified = true, proof_count = v_proofs,\n      notes = p_notes, status = 'completed', updated_at = v_now;\n    update public.shipments\n       set status = 'Delivered', driver_status = 'delivered',\n           delivery_note_status = 'Completed', updated_at = v_now\n     where id = v_ship.id;\n  end if;\n\n  update public.driver_run_stops\n     set status = 'completed', completed_at = v_now, updated_at = v_now\n   where id = v_stop.id;\n\n  if not exists (\n    select 1 from public.driver_run_stops\n    where run_id = v_run.id and status not in ('completed', 'failed')\n  ) then\n    update public.driver_runs set status = 'completed', completed_at = v_now, updated_at = v_now\n     where id = v_run.id;\n  end if;\n\n  return jsonb_build_object(\n    'shipmentId', v_ship.id,\n    'status', case when v_stop.stop_type = 'collection' then 'Collected' else 'Delivered' end,\n    'verifiedBy', case when v_scanned then 'qr' else 'code' end,\n    'proofCount', v_proofs,\n    'deliveryNote', v_note);\nend $$;\n\ngrant execute on function public.complete_driver_handover(uuid, text, text) to authenticated;\n\n\n-- The two automatic status moves nobody should have to remember.\n--\n--   Collected            -> At Warehouse          at 23:59, London time\n--   At Warehouse         -> Enroute to Zimbabwe   5 days after the period's\n--                                                 last scheduled collection\n--\n-- Both are written to be safe to run repeatedly and safe to run late: they\n-- describe the state the world should be in, and moving nothing is a normal\n-- result. That is what makes overnight collections a non-issue - a stop\n-- finished at 01:00 simply gets swept the following night, with no special\n-- case for a day that ran over.\n\n/**\n * Everything collected today is at the warehouse by the end of the day.\n *\n * Scheduled hourly and gated on the London hour rather than scheduled once at\n * a fixed UTC time, because the United Kingdom changes clocks twice a year and\n * a fixed UTC job would silently drift an hour every spring - marking goods in\n * at 22:59 through the summer, before the last van is back.\n */\ncreate or replace function public.sweep_collected_to_warehouse(p_force boolean default false)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_local timestamp := now() at time zone 'Europe/London';\n  v_moved integer := 0;\nbegin\n  -- pg_cron calls this with no JWT, so a null caller is the scheduler. Any\n  -- real caller has to be an admin: these routines move every shipment in the\n  -- business between states.\n  if auth.uid() is not null and not public.is_operations_admin() then\n    raise exception 'Admin access required' using errcode = '42501';\n  end if;\n  if not p_force and extract(hour from v_local) <> 23 then\n    return jsonb_build_object('skipped', true, 'reason', 'not 23:00 in London', 'localHour',\n                              extract(hour from v_local));\n  end if;\n\n  with moved as (\n    update public.shipments\n       set status = 'At Warehouse', updated_at = now()\n     where status = 'Collected'\n       and deleted_at is null\n    returning id\n  )\n  select count(*) into v_moved from moved;\n\n  if v_moved > 0 then\n    insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\n    values (null, 'SWEEP_AT_WAREHOUSE', 'SHIPMENT', null,\n            jsonb_build_object('moved', v_moved, 'at', now()));\n  end if;\n\n  return jsonb_build_object('moved', v_moved, 'status', 'At Warehouse');\nend $$;\n\n/**\n * Goods leave for Zimbabwe five days after the last collection of their period.\n *\n * \"Last collection of the period\" is the latest *scheduled* date across that\n * period's routes (collection_schedules.pickup_on), not the last collection\n * actually recorded — a route that slips would otherwise keep pushing the\n * departure date back, and the container does not wait.\n *\n * A shipment's period is taken from the shipment itself where it is set, and\n * from its collection schedule where it is not; older bookings only carry the\n * schedule.\n */\ncreate or replace function public.sweep_warehouse_to_enroute(\n  p_force boolean default false,\n  p_days integer default 5\n) returns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_local timestamp := now() at time zone 'Europe/London';\n  v_moved integer := 0;\nbegin\n  -- pg_cron calls this with no JWT, so a null caller is the scheduler. Any\n  -- real caller has to be an admin: these routines move every shipment in the\n  -- business between states.\n  if auth.uid() is not null and not public.is_operations_admin() then\n    raise exception 'Admin access required' using errcode = '42501';\n  end if;\n  -- Once a day is plenty; 06:00 London means the change is there when the\n  -- office opens rather than appearing mid-morning.\n  if not p_force and extract(hour from v_local) <> 6 then\n    return jsonb_build_object('skipped', true, 'reason', 'not 06:00 in London');\n  end if;\n\n  with period_end as (\n    select cs.collection_period_id as period_id, max(cs.pickup_on) as last_pickup\n      from public.collection_schedules cs\n     where cs.collection_period_id is not null\n       and cs.pickup_on is not null\n     group by cs.collection_period_id\n    having max(cs.pickup_on) <= current_date - make_interval(days => greatest(0, p_days))\n  ),\n  moved as (\n    update public.shipments s\n       set status = 'Enroute to Zimbabwe', updated_at = now()\n      from period_end pe\n     where coalesce(\n             s.collection_period_id,\n             (select cs.collection_period_id from public.collection_schedules cs\n               where cs.id = s.collection_schedule_id)\n           ) = pe.period_id\n       and s.status in ('Collected', 'At Warehouse')\n       and s.deleted_at is null\n    returning s.id\n  )\n  select count(*) into v_moved from moved;\n\n  if v_moved > 0 then\n    insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\n    values (null, 'SWEEP_ENROUTE', 'SHIPMENT', null,\n            jsonb_build_object('moved', v_moved, 'days', p_days, 'at', now()));\n  end if;\n\n  return jsonb_build_object('moved', v_moved, 'status', 'Enroute to Zimbabwe');\nend $$;\n\nrevoke all on function public.sweep_collected_to_warehouse(boolean) from public, anon;\nrevoke all on function public.sweep_warehouse_to_enroute(boolean, integer) from public, anon;\n-- Admins can run either by hand, for the first backfill and for the month a\n-- route slips and somebody needs it moved now.\ngrant execute on function public.sweep_collected_to_warehouse(boolean) to authenticated;\ngrant execute on function public.sweep_warehouse_to_enroute(boolean, integer) to authenticated;\n\ndo $$\nbegin\n  if exists (select 1 from pg_extension where extname = 'pg_cron') then\n    perform cron.unschedule(jobid) from cron.job where jobname = 'shipments-at-warehouse';\n    perform cron.schedule('shipments-at-warehouse', '59 * * * *',\n                          'select public.sweep_collected_to_warehouse()');\n\n    perform cron.unschedule(jobid) from cron.job where jobname = 'shipments-enroute';\n    perform cron.schedule('shipments-enroute', '5 * * * *',\n                          'select public.sweep_warehouse_to_enroute()');\n  else\n    raise notice 'pg_cron not installed - status sweeps must be run manually';\n  end if;\nend $$;\n\n\n-- One customer, one record, however many times they book.\n--\n-- Today sixty shipments produce fifty-eight \"customers\". Nothing groups them\n-- reliably: website and app bookings never set user_id, so every one is a\n-- guest; thirty-one of sixty carry no email, so a key built as\n-- user_id -> email -> phone silently switches identifier between two bookings\n-- by the same person; and phone numbers are stored in three different shapes\n-- (+353…, 0…, and worse), so even the phone does not match itself.\n--\n-- The customer reference cannot fix this and was never going to. MAR09266988\n-- encodes the month and year of the booking, so it identifies a *booking*.\n-- Two bookings by one person in different months have different references by\n-- design. It stays exactly as it is — it is already printed on paperwork — and\n-- customers get their own stable code alongside it.\n--\n-- Identity is the phone number first, email second, per the agreed rule.\n\n-- ---------------------------------------------------------------------------\n-- A. Normalising the things people are identified by\n-- ---------------------------------------------------------------------------\n\n/**\n * The comparable part of a phone number: its last nine digits.\n *\n * That is what survives the ways one number gets written down. +353 83 425 2477,\n * 083 425 2477 and 00353834252477 all reduce to 834252477. Nine is chosen\n * because it is short enough to ignore every country and trunk prefix in use\n * here and long enough that two different subscribers will not collide.\n */\ncreate or replace function public.phone_identity_key(p_phone text)\nreturns text\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select case\n    when length(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g')) >= 9\n      then right(regexp_replace(p_phone, '[^0-9]', '', 'g'), 9)\n    else nullif(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'), '')\n  end;\n$$;\n\ncreate or replace function public.email_identity_key(p_email text)\nreturns text\nlanguage sql\nimmutable\nset search_path = public\nas $$\n  select nullif(lower(trim(coalesce(p_email, ''))), '');\n$$;\n\n-- ---------------------------------------------------------------------------\n-- B. The customer\n-- ---------------------------------------------------------------------------\n\ncreate table if not exists public.customers (\n  id uuid primary key default gen_random_uuid(),\n  -- Stable for the life of the customer. Never encodes a date.\n  customer_code text not null unique,\n  full_name text,\n  email text,\n  phone text,\n  -- Generated, so they can never drift out of step with the raw values.\n  phone_key text generated always as (public.phone_identity_key(phone)) stored,\n  email_key text generated always as (public.email_identity_key(email)) stored,\n  country text,\n  pickup_address text,\n  pickup_city text,\n  pickup_postcode text,\n  -- Set once the customer signs up; a guest customer has none.\n  profile_id uuid references public.profiles(id) on delete set null,\n  notes text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\n-- Partial uniques: two customers may both have no phone, but no two may share\n-- one. This is what stops a duplicate being created under a race.\ncreate unique index if not exists customers_phone_key_idx\n  on public.customers (phone_key) where phone_key is not null;\ncreate unique index if not exists customers_email_key_idx\n  on public.customers (email_key) where email_key is not null;\n-- Deliberately NOT unique. One account books for several people — a customer\n-- ordering for their mother and for themselves is two customers on one login —\n-- so a profile may be attached to more than one customer record.\ndrop index if exists public.customers_profile_idx;\ncreate index if not exists customers_profile_idx\n  on public.customers (profile_id) where profile_id is not null;\n\nalter table public.shipments\n  add column if not exists customer_id uuid references public.customers(id) on delete set null;\ncreate index if not exists shipments_customer_idx on public.shipments(customer_id)\n  where deleted_at is null;\n\ndo $$\nbegin\n  if to_regclass('public.custom_quotes') is not null then\n    execute 'alter table public.custom_quotes\n             add column if not exists customer_id uuid references public.customers(id) on delete set null';\n    execute 'create index if not exists custom_quotes_customer_idx on public.custom_quotes(customer_id)';\n  end if;\nend $$;\n\ncreate sequence if not exists public.customer_code_seq start 1;\n\n/**\n * A readable, stable customer code: three letters of their name and a running\n * number — MAR00042.\n *\n * Deliberately shaped like the booking reference so staff read them the same\n * way, and deliberately without a date so it never changes.\n */\ncreate or replace function public.next_customer_code(p_name text)\nreturns text\nlanguage sql\nvolatile\nset search_path = public\nas $$\n  select rpad(\n           coalesce(nullif(upper(regexp_replace(coalesce(p_name, ''), '[^a-zA-Z]', '', 'g')), ''), 'CUS'),\n           3, 'X')\n         || lpad(nextval('public.customer_code_seq')::text, 5, '0');\n$$;\n\n-- ---------------------------------------------------------------------------\n-- C. Resolving a booking to a customer\n-- ---------------------------------------------------------------------------\n\n/**\n * Find the customer these details belong to, or create them.\n *\n * Phone wins, then email. A signed-in profile is attached to whoever is found\n * but never used to identify them — see below. Details that arrive fuller\n * than what is on file fill the gaps — a second booking that carries an email\n * where the first did not should complete the record rather than fork it — but\n * never blank out something already known.\n */\ncreate or replace function public.resolve_customer(\n  p_name text default null,\n  p_email text default null,\n  p_phone text default null,\n  p_country text default null,\n  p_address text default null,\n  p_city text default null,\n  p_postcode text default null,\n  p_profile_id uuid default null\n) returns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_phone_key text := public.phone_identity_key(p_phone);\n  v_email_key text := public.email_identity_key(p_email);\n  v_id uuid;\n  -- Not every user_id on a shipment has a profiles row behind it: live data\n  -- carries ids for users whose profile was never created or has since gone.\n  -- Passing one straight through fails the foreign key and takes the whole\n  -- backfill with it, so an id that does not resolve is treated as no id —\n  -- the customer is still created, just without a profile attached.\n  v_profile_id uuid := (select p.id from public.profiles p where p.id = p_profile_id);\nbegin\n  if v_phone_key is not null then\n    select id into v_id from public.customers where phone_key = v_phone_key limit 1;\n  end if;\n  if v_id is null and v_email_key is not null then\n    select id into v_id from public.customers where email_key = v_email_key limit 1;\n  end if;\n  -- Deliberately no fallback to the profile. Matching on \"same login\" merged\n  -- an account holder's own booking with one they made for somebody else —\n  -- two different names, two different phone numbers, one customer. The login\n  -- says who placed the booking, not who the customer is.\n\n  if v_id is null then\n    -- Two bookings by one customer landing at once would both reach here.\n    -- Rather than guess which partial unique index will fire — phone, email or\n    -- profile — let the insert fail and pick up the row that won. ON CONFLICT\n    -- can only infer one index, so it would miss the other two.\n    begin\n      insert into public.customers (customer_code, full_name, email, phone, country,\n                                    pickup_address, pickup_city, pickup_postcode, profile_id)\n      values (public.next_customer_code(p_name), nullif(trim(coalesce(p_name, '')), ''),\n              nullif(trim(coalesce(p_email, '')), ''), nullif(trim(coalesce(p_phone, '')), ''),\n              nullif(trim(coalesce(p_country, '')), ''), nullif(trim(coalesce(p_address, '')), ''),\n              nullif(trim(coalesce(p_city, '')), ''), nullif(trim(coalesce(p_postcode, '')), ''),\n              v_profile_id)\n      returning id into v_id;\n    exception when unique_violation then\n      select id into v_id from public.customers\n       where (v_phone_key is not null and phone_key = v_phone_key)\n          or (v_email_key is not null and email_key = v_email_key)\n       limit 1;\n      if v_id is null then raise; end if;\n    end;\n  else\n    update public.customers set\n      full_name = coalesce(full_name, nullif(trim(coalesce(p_name, '')), '')),\n      email = coalesce(email, nullif(trim(coalesce(p_email, '')), '')),\n      phone = coalesce(phone, nullif(trim(coalesce(p_phone, '')), '')),\n      country = coalesce(country, nullif(trim(coalesce(p_country, '')), '')),\n      pickup_address = coalesce(pickup_address, nullif(trim(coalesce(p_address, '')), '')),\n      pickup_city = coalesce(pickup_city, nullif(trim(coalesce(p_city, '')), '')),\n      pickup_postcode = coalesce(pickup_postcode, nullif(trim(coalesce(p_postcode, '')), '')),\n      profile_id = coalesce(profile_id, v_profile_id),\n      updated_at = now()\n    where id = v_id;\n  end if;\n\n  return v_id;\nend $$;\n\n/**\n * Every booking joins its customer, whichever door it came in by.\n *\n * A trigger rather than an edit to each booking routine: bookings arrive from\n * the website, the customer app, the WhatsApp bot and manual admin entry, and\n * only a trigger catches all of them and anything added later.\n */\ncreate or replace function public.link_shipment_customer()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_sender jsonb := coalesce(new.metadata->'sender', new.metadata->'senderDetails', '{}'::jsonb);\n  v_name text := coalesce(\n    nullif(trim(v_sender->>'name'), ''),\n    nullif(trim(concat_ws(' ', v_sender->>'firstName', v_sender->>'lastName')), ''));\nbegin\n  if new.customer_id is not null then\n    return new;\n  end if;\n\n  new.customer_id := public.resolve_customer(\n    v_name,\n    v_sender->>'email',\n    coalesce(v_sender->>'phone', new.metadata->>'whatsappNumber'),\n    coalesce(v_sender->>'country', new.origin),\n    v_sender->>'address',\n    v_sender->>'city',\n    coalesce(v_sender->>'postcode', v_sender->>'postalCode'),\n    new.user_id);\n\n  return new;\nend $$;\n\ndrop trigger if exists shipments_link_customer on public.shipments;\ncreate trigger shipments_link_customer\n  before insert or update of metadata, user_id on public.shipments\n  for each row\n  execute function public.link_shipment_customer();\n\n-- ---------------------------------------------------------------------------\n-- D. Backfill, and a report of what it merged\n-- ---------------------------------------------------------------------------\n\n/**\n * Link every existing shipment to a customer, merging as it goes.\n *\n * Ordered oldest first so the earliest booking names the customer and their\n * code, which keeps the codes in a sensible order and means the name on file\n * is the one they first gave.\n */\ncreate or replace function public.backfill_customers()\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row record;\n  v_linked integer := 0;\n  v_before integer;\n  v_after integer;\nbegin\n  if auth.uid() is not null and not public.is_operations_admin() then\n    raise exception 'Admin access required' using errcode = '42501';\n  end if;\n\n  select count(*) into v_before from public.customers;\n\n  for v_row in\n    select id from public.shipments\n     where customer_id is null and deleted_at is null\n     order by created_at\n  loop\n    -- The trigger does the work; touching metadata is what fires it.\n    update public.shipments set metadata = metadata where id = v_row.id;\n    v_linked := v_linked + 1;\n  end loop;\n\n  select count(*) into v_after from public.customers;\n\n  return jsonb_build_object(\n    'shipmentsLinked', v_linked,\n    'customersBefore', v_before,\n    'customersAfter', v_after,\n    'customersCreated', v_after - v_before);\nend $$;\n\nrevoke all on function public.backfill_customers() from public, anon;\ngrant execute on function public.backfill_customers() to authenticated;\n\n/**\n * What the merge actually did: every customer holding more than one booking,\n * with the distinct names, emails and phones that were folded together.\n *\n * This is the check on the automatic merge — a row here listing two different\n * people's names is the signal that a shared phone number merged two\n * customers, and admin can split them.\n */\ncreate or replace function public.customer_merge_report()\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce(jsonb_agg(r order by r->>'shipments' desc), '[]'::jsonb)\n  from (\n    select jsonb_build_object(\n      'customerId', c.id,\n      'customerCode', c.customer_code,\n      'name', c.full_name,\n      'phone', c.phone,\n      'email', c.email,\n      'shipments', count(s.id),\n      'distinctNames', (select coalesce(jsonb_agg(distinct n), '[]'::jsonb) from (\n         select coalesce(nullif(trim(s2.metadata->'sender'->>'name'), ''),\n                nullif(trim(concat_ws(' ', s2.metadata->'sender'->>'firstName',\n                                           s2.metadata->'sender'->>'lastName')), '')) as n\n         from public.shipments s2 where s2.customer_id = c.id) x where n is not null),\n      'distinctPhones', (select coalesce(jsonb_agg(distinct p), '[]'::jsonb) from (\n         select nullif(trim(s3.metadata->'sender'->>'phone'), '') as p\n         from public.shipments s3 where s3.customer_id = c.id) y where p is not null)\n    ) as r\n    from public.customers c\n    join public.shipments s on s.customer_id = c.id and s.deleted_at is null\n    group by c.id, c.customer_code, c.full_name, c.phone, c.email\n    having count(s.id) > 1\n  ) grouped;\n$$;\n\nrevoke all on function public.customer_merge_report() from public, anon;\ngrant execute on function public.customer_merge_report() to authenticated;\n\n-- ---------------------------------------------------------------------------\n-- E. Access\n-- ---------------------------------------------------------------------------\n\nalter table public.customers enable row level security;\n\ndrop policy if exists \"Staff manage customers\" on public.customers;\ncreate policy \"Staff manage customers\" on public.customers\n  for all to authenticated\n  using (public.is_operations_admin() or public.is_finance_staff())\n  with check (public.is_operations_admin() or public.is_finance_staff());\n\n-- A signed-in customer may read their own record, which is what lets the app\n-- and the website show them everything booked under it rather than only the\n-- shipments that happen to carry their user_id.\ndrop policy if exists \"Customers read own record\" on public.customers;\ncreate policy \"Customers read own record\" on public.customers\n  for select to authenticated\n  using (profile_id = auth.uid());\n\n/**\n * The portal shows a customer everything booked under their record.\n *\n * Until now it could only show shipments carrying their user_id, and website\n * bookings never set one — so a customer who booked as a guest and then\n * created an account saw an empty account. RLS policies are OR'd together, so\n * this widens what they can see without loosening anything already in place.\n */\ndrop policy if exists \"Customers read shipments on their record\" on public.shipments;\ncreate policy \"Customers read shipments on their record\" on public.shipments\n  for select to authenticated\n  using (\n    customer_id is not null\n    and customer_id in (select id from public.customers where profile_id = auth.uid())\n  );\n\n/**\n * Signing up claims the bookings already made with that phone or email.\n *\n * The whole point of unifying customers is undone if creating an account makes\n * a fifty-ninth record. A new or updated profile is attached to the customer\n * that already matches it, and only creates one when nothing does.\n */\ncreate or replace function public.link_profile_customer()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_customer uuid;\nbegin\n  -- Staff are not customers.\n  if coalesce(new.is_admin, false)\n     or lower(coalesce(new.role, 'customer')) in ('admin', 'driver', 'finance', 'logistics', 'dispatcher') then\n    return new;\n  end if;\n\n  v_customer := public.resolve_customer(\n    new.full_name, new.email, new.phone_number, new.country,\n    new.pickup_address, new.pickup_city, null, new.id);\n\n  -- Hand them the bookings they made before they had an account.\n  --\n  -- Setting user_id, rather than only linking the customer, is deliberate:\n  -- every screen in the app and on the website already asks \"shipments where\n  -- user_id is me\". Claiming the rows here makes all of them correct at once,\n  -- instead of a dozen queries each needing to learn about customers and one\n  -- of them being missed. Only unclaimed rows are touched, so a shipment that\n  -- already belongs to somebody is never reassigned.\n  update public.shipments\n     set user_id = new.id\n   where user_id is null\n     and deleted_at is null\n     and customer_id is not null\n     and (customer_id = v_customer\n          or customer_id in (select id from public.customers where profile_id = new.id));\n\n  return new;\nend $$;\n\ndrop trigger if exists profiles_link_customer on public.profiles;\ncreate trigger profiles_link_customer\n  after insert or update of email, phone_number on public.profiles\n  for each row\n  execute function public.link_profile_customer();\n\n-- ---------------------------------------------------------------------------\n-- F. What the admin screens read\n-- ---------------------------------------------------------------------------\n\n/**\n * The customer list: one row per customer, with the totals staff scan for.\n *\n * This replaces admin_customer_records, whose job was to *reconstruct* customers\n * from scattered booking details every time it ran. That reconstruction is what\n * produced fifty-eight customers from sixty shipments. Identity is a stored\n * fact now, so this only has to add up what hangs off it.\n */\ncreate or replace function public.admin_customer_list()\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case when not (public.is_operations_admin() or public.is_finance_staff())\n    then jsonb_build_object('error', 'Admin or finance access required')\n    else coalesce((\n      select jsonb_agg(row order by row->>'lastActivity' desc nulls last)\n      from (\n        select jsonb_build_object(\n          'key', c.id,\n          'customerId', c.id,\n          'profileId', c.profile_id,\n          'customerCode', c.customer_code,\n          'fullName', coalesce(c.full_name, 'Unknown customer'),\n          'email', c.email,\n          'phone', c.phone,\n          'country', c.country,\n          'pickupAddress', nullif(trim(concat_ws(', ', c.pickup_address, c.pickup_city)), ''),\n          'shipmentCount', count(distinct s.id),\n          'quoteCount', 0,\n          'lifetimeValue', coalesce(sum(inv.total), 0),\n          'outstanding', coalesce(sum(inv.total), 0) - coalesce(sum(inv.paid), 0),\n          'currency', coalesce(max(inv.currency), 'GBP'),\n          'lastBooking', max(s.created_at),\n          'lastActivity', greatest(coalesce(max(s.created_at), c.created_at), c.created_at),\n          'active', true\n        ) as row\n        from public.customers c\n        left join public.shipments s\n          on s.customer_id = c.id and s.deleted_at is null\n        left join lateral (\n          select\n            coalesce((select sum(coalesce((i->>'quantity')::numeric,0) * coalesce((i->>'unitPrice')::numeric,0))\n                      from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'items')='array'\n                                                     then s.metadata->'invoice'->'items' else '[]'::jsonb end) i), 0)\n            - coalesce((s.metadata->'invoice'->>'discount')::numeric, 0) as total,\n            coalesce((select sum(coalesce((p->>'amount')::numeric,0))\n                      from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'payments')='array'\n                                                     then s.metadata->'invoice'->'payments' else '[]'::jsonb end) p), 0) as paid,\n            s.metadata->'invoice'->>'currency' as currency\n        ) inv on true\n        group by c.id, c.profile_id, c.customer_code, c.full_name, c.email, c.phone,\n                 c.country, c.pickup_address, c.pickup_city, c.created_at\n      ) grouped\n    ), '[]'::jsonb)\n  end;\n$$;\n\nrevoke all on function public.admin_customer_list() from public, anon;\ngrant execute on function public.admin_customer_list() to authenticated;\n\n/**\n * A customer's statement: every charge and every payment, oldest first, with a\n * running balance.\n *\n * Built from the same metadata.invoice the invoice, the app and the website all\n * read, so the statement cannot disagree with the documents it summarises.\n */\ncreate or replace function public.customer_statement(p_customer_id uuid)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_rows jsonb;\n  v_allowed boolean;\nbegin\n  select public.is_operations_admin() or public.is_finance_staff()\n         or exists (select 1 from public.customers c\n                     where c.id = p_customer_id and c.profile_id = auth.uid())\n    into v_allowed;\n  if not v_allowed then\n    raise exception 'Not your statement' using errcode = '42501';\n  end if;\n\n  with charges as (\n    select s.id as shipment_id, s.created_at as at,\n           coalesce(s.metadata->'invoice'->>'invoiceNumber',\n                    'INV-' || coalesce(s.customer_reference, s.tracking_number, '')) as ref,\n           'charge' as kind,\n           coalesce((select sum(coalesce((i->>'quantity')::numeric,0) * coalesce((i->>'unitPrice')::numeric,0))\n                     from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'items')='array'\n                                                    then s.metadata->'invoice'->'items' else '[]'::jsonb end) i), 0)\n           - coalesce((s.metadata->'invoice'->>'discount')::numeric, 0) as amount,\n           coalesce(s.metadata->'invoice'->>'currency', 'GBP') as currency,\n           null::text as method\n      from public.shipments s\n     where s.customer_id = p_customer_id and s.deleted_at is null\n       and s.metadata->'invoice' is not null\n  ),\n  credits as (\n    select s.id as shipment_id,\n           coalesce((p->>'date')::timestamptz, s.created_at) as at,\n           coalesce(s.metadata->'invoice'->>'invoiceNumber', s.tracking_number) as ref,\n           'payment' as kind,\n           -coalesce((p->>'amount')::numeric, 0) as amount,\n           coalesce(s.metadata->'invoice'->>'currency', 'GBP') as currency,\n           p->>'method' as method\n      from public.shipments s\n      cross join lateral jsonb_array_elements(\n        case when jsonb_typeof(s.metadata->'invoice'->'payments')='array'\n             then s.metadata->'invoice'->'payments' else '[]'::jsonb end) p\n     where s.customer_id = p_customer_id and s.deleted_at is null\n  ),\n  ordered as (\n    -- Order by the calendar day, then charge before payment.\n    --\n    -- Not by timestamp: a payment carries a plain date, which is midnight,\n    -- while the invoice it settles carries the booking's real time of day. Any\n    -- payment therefore sorts ahead of the invoice it pays, and the statement\n    -- opens hundreds in credit before the first bill is raised.\n    select *, sum(amount) over (order by at::date, kind, at\n                                rows between unbounded preceding and current row) as balance\n      from (select * from charges union all select * from credits) both_sides\n  )\n  select coalesce(jsonb_agg(jsonb_build_object(\n           'shipmentId', shipment_id, 'at', at, 'reference', ref, 'kind', kind,\n           'amount', amount, 'currency', currency, 'method', method, 'balance', balance\n         ) order by at::date, kind, at), '[]'::jsonb)\n    into v_rows from ordered;\n\n  return v_rows;\nend $$;\n\nrevoke all on function public.customer_statement(uuid) from public, anon;\ngrant execute on function public.customer_statement(uuid) to authenticated;\n";

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

function getAdminClient() {
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) throw new Error("Supabase service role is not configured");
  return createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
}

async function requireAdmin(req: Request) {
  const authHeader = req.headers.get("Authorization");
  if (!authHeader) return null;
  const authClient = createClient(SUPABASE_URL, Deno.env.get("SUPABASE_ANON_KEY") || "", {
    global: { headers: { Authorization: authHeader } },
  });
  const { data: { user } } = await authClient.auth.getUser();
  if (!user) return null;
  const admin = getAdminClient();
  const { data: profile } = await admin.from("profiles").select("is_admin,role").eq("id", user.id).single();
  if (!profile || (!profile.is_admin && !["admin", "logistics"].includes(String(profile.role)))) return null;
  return user;
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);

  try {
    const body = await req.json().catch(() => ({}));
    const action = String(body?.action || "verify");

    if (!(await requireAdmin(req))) return json({ error: "Admin access required" }, 403);
    if (!SUPABASE_DB_URL) return json({ error: "SUPABASE_DB_URL is not available" }, 500);

    const sql = postgres(SUPABASE_DB_URL, { prepare: false });
    try {
      if (action === "setup") {
        if (!SETUP_SQL.trim()) {
          return json({ error: "SETUP_SQL is empty — run tools/embed-schema-setup-sql.cjs and redeploy" }, 500);
        }
        await sql.unsafe(SETUP_SQL);
        return json({ ok: true, message: "Schema is up to date.", chars: SETUP_SQL.length });
      }

      if (action === "verify") {
        // Every probe stands alone. This action's whole point is describing a
        // database that may not have been migrated yet, so a missing table or
        // column must read as "not there" rather than take the report down.
        const probe = async (sqlText: string, fallback: unknown) => {
          try {
            const [row] = await sql.unsafe(sqlText);
            return row ?? fallback;
          } catch {
            return fallback;
          }
        };

        const table = await probe(
          `select to_regclass('public.collection_slots') is not null as present`, { present: false });
        const dates = await probe(
          `select count(*) filter (where pickup_on is not null)::int as with_date, count(*)::int as total
             from public.collection_schedules`, { with_date: null, total: null });
        const unparsed = await probe(
          `select coalesce(string_agg(pickup_date, ' | '), '(none)') as samples
             from public.collection_schedules where pickup_on is null and coalesce(pickup_date,'') <> ''`,
          { samples: "n/a" });
        const job = await probe(
          `select count(*)::int as scheduled from cron.job where jobname = 'collection-slot-reminders'`,
          { scheduled: null });
        const functions = await probe(
          `select count(*)::int as present from pg_proc
            where proname in ('confirm_collection_slot','dispatch_set_collection_slot',
                              'mark_collection_customer_informed','queue_collection_slot_reminders')`,
          { present: 0 });
        const pickup = await probe(
          `select count(*) filter (where address_type = 'pickup')::int as pickup,
                  count(*) filter (where address_type = 'delivery')::int as delivery
             from public.customer_addresses`, { pickup: null, delivery: null });
        const drums = await probe(
          `select (value->>'metalDrumPurchase') as metal, (value->>'plasticDrumPurchase') as plastic
             from public.app_configuration where key = 'booking_fees'`, {});
        const booking = await probe(
          `select to_regprocedure('public.create_customer_booking_v2(jsonb)') is not null as wrapped`,
          { wrapped: false });

        const runs = await probe(
          `select count(*)::int as runs,
                  count(*) filter (where collection_date is not null)::int as dated
             from public.collection_runs`, { runs: null, dated: null });
        const filed = await probe(
          `select count(*) filter (where collection_run_id is not null)::int as filed,
                  count(*)::int as pending
             from public.shipments
            where deleted_at is null
              and lower(coalesce(status,'')) in ('booking confirmed','confirmed','pending')
              and created_at >= now() - interval '60 days'`, { filed: null, pending: null });

        return json({
          ok: true,
          collection_slots_table: table.present ?? false,
          collection_runs: `${runs.runs ?? "n/a"} runs (${runs.dated ?? "n/a"} dated)`,
          recent_pending_filed: `${filed.filed ?? "n/a"}/${filed.pending ?? "n/a"}`,
          schedules_with_parsed_date: `${dates.with_date ?? "n/a"}/${dates.total ?? "n/a"}`,
          unparsed_pickup_dates: unparsed.samples,
          rpcs_present: `${functions.present ?? 0}/4`,
          reminder_cron_scheduled: job.scheduled ?? "unknown",
          saved_addresses: `${pickup.pickup ?? "n/a"} pickup / ${pickup.delivery ?? "n/a"} delivery`,
          drum_purchase_prices: `metal ${drums.metal ?? "?"} / plastic ${drums.plastic ?? "?"}`,
          booking_fn_wrapped_for_drums: booking.wrapped ?? false,
        });
      }

      return json({ error: `Unknown action: ${action}` }, 400);
    } finally {
      await sql.end({ timeout: 5 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Unexpected error" }, 500);
  }
});
